const std = @import("std");
const builtin = @import("builtin");
// build.zig.zon의 .version을 버전 단일 출처로 읽는다(인앱 새 버전 안내가 이 값과 GitHub
// releases/latest tag를 비교 — distribution.md). 릴리스 시 .version만 올리면 앱 버전도 따라간다.
const build_zig_zon = @import("build.zig.zon");

/// Zig 0.16 Build의 test-server IPC 대신 project-owned simple runner를 쓴다.
/// `simple_test_runner`는 standard terminal runner와 같은 test/leak/log failure
/// semantics를 exit code로 보존한다. docs/development-commands.md를 함께 갱신한다.
fn addProjectTest(b: *std.Build, options: std.Build.TestOptions) *std.Build.Step.Compile {
    var configured = options;
    configured.test_runner = .{
        .path = b.path("tools/simple_test_runner.zig"),
        .mode = .simple,
    };
    return b.addTest(configured);
}

fn linkSessionHostNotificationAdapter(b: *std.Build, compile: *std.Build.Step.Compile) void {
    if (b.sysroot) |sdk| {
        compile.root_module.addSystemFrameworkPath(.{
            .cwd_relative = b.fmt("{s}/System/Library/Frameworks", .{sdk}),
        });
    }
    compile.root_module.addIncludePath(b.path("src/platform/macos"));
    compile.root_module.addCSourceFile(.{
        .file = b.path("src/platform/macos/session_host_notification_adapter.m"),
        .flags = &.{
            "-fobjc-arc",
            "-fno-sanitize=undefined",
            "-iframeworkwithsysroot",
            "/System/Library/Frameworks",
            "-iwithsysroot",
            "/usr/include",
        },
    });
    compile.root_module.addCSourceFile(.{
        .file = b.path("src/platform/macos/session_host_notification_route.c"),
        .flags = &.{},
    });
    compile.root_module.linkFramework("Foundation", .{});
    compile.root_module.linkFramework("UserNotifications", .{});
}

/// `check-targets` analyzes the macOS executable from Linux without owning an Apple SDK.
/// Keep that compile-only gate honest about the C ABI without pretending that it can build
/// the product platform adapter. Product and macOS-host builds always use the Objective-C
/// implementation above; this stub is never installed or executed.
fn linkSessionHostNotificationCompileStub(b: *std.Build, compile: *std.Build.Step.Compile) void {
    compile.root_module.addIncludePath(b.path("src/platform/macos"));
    compile.root_module.addCSourceFile(.{
        .file = b.path("tests/fixtures/session_host_notification_adapter_compile_stub.c"),
        .flags = &.{},
    });
}

pub fn build(b: *std.Build) void {
    // macOS 배포 하한을 11.0(Big Sur, Apple Silicon 시작 버전)으로 고정해 구형 macOS에서도
    // 실행되게 한다. 단 이 기본값은 macOS 호스트에서 빌드할 때만 건다.
    //   os_version_min을 모든 호스트의 default_target에 박으면, Linux CI에서 target이
    //   native-native.11.0이 되어 std.Target.Query.isNative()가 false가 되고, Zig가 native
    //   시스템 라이브러리 경로(libvterm 등) 탐지를 꺼버린다("searched paths: none") →
    //   외부 오라클 빌드가 깨진다. 그래서 macOS 호스트에서만 min을 덮어쓴다.
    // macOS에서는 cpu_arch/os_tag/abi를 null로 둬 native를 유지하므로(=os_version_min만 덮어씀)
    // Zig가 시스템 SDK(Metal/CoreText 등 프레임워크 헤더)를 계속 자동 탐지한다. 버전을
    // triple로 명시(예: aarch64-macos.11.0)하면 cross-compile로 간주돼 SDK 탐지가 꺼지므로
    // 그 방식은 쓰지 않는다. -Dtarget을 주면 그 값이 우선한다. Swift app host도
    // swiftMacOSTarget()이 이 min 버전을 그대로 읽어 함께 낮아진다.
    const default_target_query: std.Target.Query = if (builtin.os.tag == .macos)
        .{ .os_version_min = .{ .semver = .{ .major = 11, .minor = 0, .patch = 0 } } }
    else
        .{};
    const target = b.standardTargetOptions(.{ .default_target = default_target_query });
    const optimize = b.standardOptimizeOption(.{});
    const release_tag = b.option([]const u8, "release-tag", "Release tag that must equal v<build.zig.zon version>");

    // 제품 version의 단일 출처는 build.zig.zon이다. source plist는 capability template일 뿐이며,
    // bare executable의 __TEXT,__info_plist와 .app bundle이 같은 generated bytes를 소비한다.
    const macos_info_plist_generate = b.addSystemCommand(&.{
        "sh", "tools/render-macos-info-plist.sh", "render",
    });
    macos_info_plist_generate.addFileArg(b.path("src/platform/macos/MaruAppHost-Info.plist.in"));
    const macos_info_plist = macos_info_plist_generate.addOutputFileArg("MaruAppHost-Info.plist");
    macos_info_plist_generate.addArg(build_zig_zon.version);
    macos_info_plist_generate.setCwd(b.path("."));

    // macOS에서 os_version_min을 박으면 Zig가 cross-compile로 보고(std.Target.Query.isNative()=false)
    // SDK 프레임워크/라이브러리 자동 탐지를 꺼버린다("searched paths: none" — Xcode 26/Zig 0.16 실측;
    // 위 "macOS는 native 유지라 자동 탐지" 주석의 가정이 이 조합에서 깨졌다). 배포 하한(11.0)은 유지해야
    // 하므로 SDK 경로를 빌드 타임에 xcrun으로 얻어 공유 모듈에 명시 추가해 자동 탐지 부재를 메운다.
    // (-Dtarget을 주면 target.result가 그 값이라 native면 이 보강이 무해하게 중복될 뿐이다.)
    const macos_sdk: ?[]const u8 = if (target.result.os.tag == .macos and builtin.os.tag == .macos) blk: {
        const out = b.run(&.{ "xcrun", "--sdk", "macosx", "--show-sdk-path" });
        const trimmed = std.mem.trim(u8, out, " \t\r\n");
        break :blk if (trimmed.len > 0) trimmed else null;
    } else null;

    const shutdown_wire_contract_mod = b.createModule(.{
        .root_source_file = b.path("src/shutdown_wire_contract.zig"),
        .target = target,
    });
    const maru_mod = b.addModule("maru", .{
        .root_source_file = b.path("src/maru.zig"),
        .target = target,
        .link_libc = true,
        .imports = &.{.{ .name = "shutdown_wire_contract", .module = shutdown_wire_contract_mod }},
    });
    // terminfo 소스는 src/ 밖(terminfo/maru.terminfo — tools/·docs가 공유하는 단일 출처)이라 @embedFile이
    // 직접 못 읽는다. 빌드 import로 등록해 cli/ssh.zig가 @embedFile("maru_terminfo")로 바이너리에 심는다
    // (maru ssh 자기완결성 — 로컬 설치 없이 원격 전파). 파일을 옮기지 않아 참조 중복이 없다.
    maru_mod.addAnonymousImport("maru_terminfo", .{ .root_source_file = b.path("terminfo/maru.terminfo") });
    // docs/configuration.md도 src/ 밖이라 @embedFile이 직접 못 읽는다. config 스키마 doc-drift 가드(CS-3,
    // src/config/schema.zig 테스트)가 @embedFile("config_doc_md")로 박아 모든 스키마 키가 표에 문서화됐는지 검증한다.
    maru_mod.addAnonymousImport("config_doc_md", .{ .root_source_file = b.path("docs/configuration.md") });
    // SDK 프레임워크/라이브러리/헤더 경로를 공유 모듈에 명시 — cross 처리로 꺼진 자동 탐지를 메운다.
    // maru를 import하는 Compile(코어 테스트, app host, .m 브리지 링크 포함)의 link에 합쳐진다.
    if (macos_sdk) |sdk| {
        // cross-compile(예: arm64 호스트에서 x86_64 빌드) macOS 빌드의 SDK 통합:
        //  (1) framework 검색 경로는 명시한다 — Zig는 cross에서 sysroot가 있어도 -iframework를
        //      자동 추가하지 않아 CoreText.h/Metal.h를 못 찾는다.
        //  (2) SDK를 sysroot로 넘긴다 — framework path만으로는 clang이 SDK를 sysroot로 인식하지
        //      못해 Security.framework가 의존하는 usr/include/libDER/* 헤더를 못 찾고("file not found")
        //      availability 메타데이터(예: CGToneMapping macOS 15.0)도 어긋난다.
        //  (3) usr/include·usr/lib는 절대경로로 추가하지 않는다 — sysroot가 자동 해석하며, 절대로
        //      또 주면 sysroot prefix와 이중 결합돼(…/SDK/…/SDK/usr/lib) 깨진다.
        // universal 빌드(arm64 + x86_64 lipo)에 필요하고, native에도 무해하다.
        maru_mod.addSystemFrameworkPath(.{ .cwd_relative = b.fmt("{s}/System/Library/Frameworks", .{sdk}) });
        if (b.sysroot == null) b.sysroot = sdk;
    }
    const test_support_mod = b.addModule("test_support", .{
        .root_source_file = b.path("tests/support/artifacts.zig"),
        .target = target,
    });
    const session_host_product_options = b.addOptions();
    session_host_product_options.addOption(bool, "allow_validation_only_restore", false);

    const exe = b.addExecutable(.{
        .name = "maru",
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/main.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "session_host_build_options", .module = session_host_product_options.createModule() },
            },
        }),
    });

    // W7.1: Win32 창은 user32/gdi32를 부른다. `extern "user32"`만으로는 이 exe에 import가 안 붙어
    // 호출이 조용히 실패한다(실측: `RegisterClassExW`도 시스템 `STATIC` 클래스 `CreateWindowExW`도
    // null/0을 내면서 `GetLastError`는 0이었다 — "함수가 아예 안 돈" 모양이다). 명시적으로 링크한다.
    if (target.result.os.tag == .windows) {
        exe.root_module.linkSystemLibrary("user32", .{});
        exe.root_module.linkSystemLibrary("gdi32", .{});
        // W7.2a: D3D11 표시 경로. `extern "d3d11"`/`extern "dxgi"`만으로는 import가 안 붙는다 —
        // user32에서 겪은 것과 같은 부류다(그때는 `RegisterClassExW`가 조용히 0을 냈다).
        exe.root_module.linkSystemLibrary("d3d11", .{});
        exe.root_module.linkSystemLibrary("dxgi", .{});
        // W7.3: DirectWrite 글리프 래스터라이저.
        exe.root_module.linkSystemLibrary("dwrite", .{});
        // W7.4c: IME 조합 문자열(`ImmGetCompositionStringW`).
        exe.root_module.linkSystemLibrary("imm32", .{});
    }
    if (target.result.os.tag == .macos) {
        linkSessionHostNotificationAdapter(b, exe);
    }

    b.installArtifact(exe);

    // W7.6: 번들 ConPTY. **인박스 conhost 가 낡으면 없는 기능이 있다**(마우스 리포팅 — 계약 §4.3).
    // 배치는 NuGet 패키지의 `build/native/*.targets` 가 정한 그대로다: `conpty.dll` 은 실행 파일 옆,
    // `OpenConsole.exe` 는 아키텍처 하위 폴더. **틀리면 conpty.dll 이 시스템 conhost 로 조용히
    // 되돌아가므로**(실패하지 않는다) 자리를 바꾸지 않는다.
    //
    // 파일이 없어도 빌드가 깨지지 않게 한다 — 소스 체크아웃에서 `assets/` 를 빼도 돌아야 하고,
    // 런타임은 `pty/windows.zig` 가 kernel32 로 접는다.
    if (target.result.os.tag == .windows and target.result.cpu.arch == .x86_64) {
        const dll = "assets/windows/conpty/x64/conpty.dll";
        const host = "assets/windows/conpty/x64/OpenConsole.exe";
        const io = b.graph.io;
        if (b.build_root.handle.access(io, dll, .{})) |_| {
            b.getInstallStep().dependOn(&b.addInstallBinFile(b.path(dll), "conpty.dll").step);
        } else |_| {}
        if (b.build_root.handle.access(io, host, .{})) |_| {
            b.getInstallStep().dependOn(&b.addInstallBinFile(b.path(host), "x64/OpenConsole.exe").step);
        } else |_| {}
    }

    const run_step = b.step("run", "Run the development CLI");
    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| {
        run_cmd.addArgs(args);
    }
    run_step.dependOn(&run_cmd.step);

    const demo_step = b.step("demo", "Run the headless PTY demo");
    const demo_cmd = b.addRunArtifact(exe);
    demo_cmd.step.dependOn(b.getInstallStep());
    demo_cmd.addArg("demo");
    demo_step.dependOn(&demo_cmd.step);

    // ── 모바일 어댑터 정적 라이브러리 ────────────────────────────────────────────
    // **Zig 는 `.a` 까지만 만든다.** iOS 용 `libSystem` 을 Zig 가 링크하지 못해(실측)
    // 링크는 플랫폼 툴체인(clang/NDK)이 맡는다 — 실제 앱에서도 이 구조가 된다.
    // 기기 조작(설치·실행·캡쳐)은 `tools/mobile-harness/run.sh` 가, 빌드는 여기가 소유한다.
    //
    // **Debug 는 iOS 에서 링크가 깨진다.** std 의 스택 트레이스 경로가 시뮬레이터 SDK 에 없는
    // `_dyld_get_image_header_containing_address` 를 참조한다. `mobile_bridge.zig` 의
    // `simple_panic` 이 ReleaseSafe/ReleaseFast 에서 그 경로를 걷어내므로 `-Doptimize` 로
    // 그중 하나를 준다(안전 검사는 ReleaseSafe 에서 그대로 산다).
    //
    // CI 에는 붙이지 않는다(사용자 결정) — Xcode·NDK·에뮬레이터가 필요해 러너 비용이 크고
    // 지금 막아야 할 회귀가 없다(docs/plans/mobile-platform.md).
    {
        const mobile_libs_step = b.step("mobile-libs", "Build the mobile adapter static libraries (iOS/Android)");
        const MobileTarget = struct {
            step_name: []const u8,
            lib_name: []const u8,
            query: std.Target.Query,
            /// Android 는 PIE 가 필수라 정적 라이브러리도 위치 독립이어야 한다(실측).
            pic: bool,
        };
        const mobile_targets = [_]MobileTarget{
            .{
                .step_name = "mobile-lib-ios-sim",
                .lib_name = "maru-mobile-ios-sim",
                .query = .{ .cpu_arch = .aarch64, .os_tag = .ios, .abi = .simulator },
                .pic = false,
            },
            .{
                .step_name = "mobile-lib-ios",
                .lib_name = "maru-mobile-ios",
                .query = .{ .cpu_arch = .aarch64, .os_tag = .ios, .abi = .none },
                .pic = false,
            },
            .{
                .step_name = "mobile-lib-android",
                .lib_name = "maru-mobile-android",
                .query = .{ .cpu_arch = .aarch64, .os_tag = .linux, .abi = .android },
                .pic = true,
            },
        };
        for (mobile_targets) |mt| {
            const mobile_target = b.resolveTargetQuery(mt.query);
            // 모듈 루트는 `maru.zig` 하나여야 한다 — chrome·renderer 를 따로 주면 둘 다
            // `icons.zig` 를 상대 경로로 끌어와 "file exists in two modules" 로 깨진다(실측).
            const mobile_maru_mod = b.createModule(.{
                .root_source_file = b.path("src/maru.zig"),
                .target = mobile_target,
                .optimize = optimize,
                .pic = if (mt.pic) true else null,
            });
            const lib = b.addLibrary(.{
                .name = mt.lib_name,
                .linkage = .static,
                .root_module = b.createModule(.{
                    .root_source_file = b.path("src/platform/mobile/mobile_bridge.zig"),
                    .target = mobile_target,
                    .optimize = optimize,
                    .pic = if (mt.pic) true else null,
                    .imports = &.{.{ .name = "maru", .module = mobile_maru_mod }},
                }),
            });
            const install = b.addInstallArtifact(lib, .{});
            const step = b.step(mt.step_name, b.fmt("Build {s}", .{mt.lib_name}));
            step.dependOn(&install.step);
            mobile_libs_step.dependOn(&install.step);
        }
    }

    // wasm 터미널 코어. `@maru-term/core` 가 싣는 배포 산출물이다.
    // **`addLibrary` 를 쓸 수 없다** — wasm 타깃에서 정적 링크는 `.wasm` 모듈이 아니라
    // `ar` 아카이브(`!<ar`)를 낸다(실측 — docs/wasm-portability.md §5). 실행 파일로 만들고
    // entry 를 끄는 것이 wasm 모듈을 얻는 경로다.
    {
        const wasm_target = b.resolveTargetQuery(.{ .cpu_arch = .wasm32, .os_tag = .freestanding });
        // 모듈 루트 하나(§mobile 과 같은 이유). `link_libc` 를 주지 않는다 — freestanding 에 libc 가 없다.
        const wasm_maru_mod = b.createModule(.{
            .root_source_file = b.path("src/maru.zig"),
            .target = wasm_target,
            .optimize = .ReleaseSmall,
        });
        const wasm = b.addExecutable(.{
            .name = "maru-vt",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/wasm/wasm_bridge.zig"),
                .target = wasm_target,
                .optimize = .ReleaseSmall,
                .imports = &.{.{ .name = "maru", .module = wasm_maru_mod }},
            }),
        });
        wasm.entry = .disabled; // `_start` 없음 — 호스트가 export 를 직접 부른다
        wasm.rdynamic = true; // export 를 심볼 테이블에 남긴다
        // **iOS Safari 는 선언된 maximum 을 먼저 검증한다.** 2 GB 같은 큰 상한을 선언하면
        // 실제로 100 MB 만 써도 instantiation 에서 OOM 으로 실패한다(docs/wasm-portability.md §5.2).
        wasm.max_memory = 64 * 1024 * 1024;

        const wasm_step = b.step("wasm-lib", "Build the WebAssembly terminal core");
        // 실행할 수 없는 타깃이라 Run step 을 만들지 않는다(check-targets 와 같은 결).
        wasm_step.dependOn(&b.addInstallArtifact(wasm, .{}).step);
        // 배포 자리로도 복사한다 — 받는 쪽에 Zig 툴체인이 없으므로 바이너리를 커밋한다.
        wasm_step.dependOn(&b.addInstallFile(wasm.getEmittedBin(), "../packages/core/wasm/maru-vt.wasm").step);
    }

    const app_smoke_step = b.step("app-smoke", "Run the app host frame smoke");
    const app_smoke_cmd = b.addRunArtifact(exe);
    app_smoke_cmd.step.dependOn(b.getInstallStep());
    app_smoke_cmd.addArg("app-smoke");
    app_smoke_step.dependOn(&app_smoke_cmd.step);

    const app_loop_smoke_step = b.step("app-loop-smoke", "Run the app frame-loop contract smoke");
    const app_loop_smoke_cmd = b.addRunArtifact(exe);
    app_loop_smoke_cmd.step.dependOn(b.getInstallStep());
    app_loop_smoke_cmd.addArg("app-loop-smoke");
    app_loop_smoke_step.dependOn(&app_loop_smoke_cmd.step);

    const app_pty_loop_smoke_step = b.step("app-pty-loop-smoke", "Run the live PTY app frame-loop smoke");
    const app_pty_loop_smoke_cmd = b.addRunArtifact(exe);
    app_pty_loop_smoke_cmd.step.dependOn(b.getInstallStep());
    app_pty_loop_smoke_cmd.addArg("app-pty-loop-smoke");
    app_pty_loop_smoke_step.dependOn(&app_pty_loop_smoke_cmd.step);

    const app_pty_interactive_loop_smoke_step = b.step("app-pty-interactive-loop-smoke", "Run the interactive shell app frame-loop smoke");
    const app_pty_interactive_loop_smoke_cmd = b.addRunArtifact(exe);
    app_pty_interactive_loop_smoke_cmd.step.dependOn(b.getInstallStep());
    app_pty_interactive_loop_smoke_cmd.addArg("app-pty-interactive-loop-smoke");
    app_pty_interactive_loop_smoke_step.dependOn(&app_pty_interactive_loop_smoke_cmd.step);

    // `win32-file-tree-smoke` 도 다른 스모크와 같이 step 으로 세운다. 처음엔 CLI 하위 명령으로만
    // 뒀는데, 이 저장소의 스모크는 전부 `zig build <이름>` 으로 도는 것이 관례라 **혼자만 안 도는
    // 것을 발견할 방법이 없었다**(적대적 검증에서 내가 직접 `no step named` 로 걸렸다).
    // Windows 전용이므로 다른 호스트에서는 rc=1 대신 **시끄럽게 건너뛴다** — 조용한 성공이 가장 나쁘다.
    const win32_file_tree_smoke_step = b.step("win32-file-tree-smoke", "Run the Windows file tree data-path smoke");
    if (target.result.os.tag == .windows) {
        const win32_file_tree_smoke_cmd = b.addRunArtifact(exe);
        win32_file_tree_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_file_tree_smoke_cmd.addArg("win32-file-tree-smoke");
        win32_file_tree_smoke_step.dependOn(&win32_file_tree_smoke_cmd.step);
    } else {
        win32_file_tree_smoke_step.dependOn(noteSkippedStep(b, "win32-file-tree-smoke", "Windows 호스트 전용 — 실제 Win32 디렉터리 순회를 잰다 (docs/windows-platform.md §2m.4)"));
    }

    // 그리기 스모크도 step 으로 세운다 — #2457 이 세운 관례다(스모크가 CLI 하위 명령으로만 있으면
    // 혼자만 안 도는 것을 발견할 방법이 없다). 이 슬라이스에서 그 규칙을 내가 다시 어겼고 적대적
    // 검증이 잡았다.
    const win32_file_tree_draw_smoke_step = b.step("win32-file-tree-draw-smoke", "Run the Windows file tree drawing smoke");
    if (target.result.os.tag == .windows) {
        const win32_file_tree_draw_smoke_cmd = b.addRunArtifact(exe);
        win32_file_tree_draw_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_file_tree_draw_smoke_cmd.addArg("win32-file-tree-draw-smoke");
        win32_file_tree_draw_smoke_step.dependOn(&win32_file_tree_draw_smoke_cmd.step);
    } else {
        win32_file_tree_draw_smoke_step.dependOn(noteSkippedStep(b, "win32-file-tree-draw-smoke", "Windows 호스트 전용 — D3D11 창을 열고 파일 트리 행을 실제로 그린다 (docs/windows-platform.md §2m.6)"));
    }

    // git 스모크도 step 으로 세운다 — #2457 이 세운 관례다(CLI 하위 명령으로만 있으면 혼자만 안 도는
    // 것을 발견할 방법이 없다).
    const win32_git_smoke_step = b.step("win32-git-smoke", "Run the Windows git backend smoke");
    if (target.result.os.tag == .windows) {
        const win32_git_smoke_cmd = b.addRunArtifact(exe);
        win32_git_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_git_smoke_cmd.addArg("win32-git-smoke");
        win32_git_smoke_step.dependOn(&win32_git_smoke_cmd.step);
    } else {
        win32_git_smoke_step.dependOn(noteSkippedStep(b, "win32-git-smoke", "Windows 호스트 전용 — git 백엔드의 Windows 갈래를 제품 경로로 잰다 (docs/windows-platform.md §2m.9)"));
    }

    const app_pty_smoke_step = b.step("app-pty-smoke", "Run the live PTY app host frame smoke");
    const app_pty_smoke_cmd = b.addRunArtifact(exe);
    app_pty_smoke_cmd.step.dependOn(b.getInstallStep());
    app_pty_smoke_cmd.addArg("app-pty-smoke");
    app_pty_smoke_step.dependOn(&app_pty_smoke_cmd.step);

    // W7.1 창 스모크는 Win32와 **대화형 데스크톱**이 필요하다 — macOS visible window smoke를 window
    // server 때문에 OS로 게이트하는 것과 같은 이유다(아래). 그래서 `check`에 넣지 않는다: 사람이
    // 평범한 세션에서 직접 돌려 눈으로 보는 스모크다.
    if (target.result.os.tag == .windows) {
        const win32_window_smoke_step = b.step("win32-window-smoke", "Open a real Win32 window and report its neutral events (needs an interactive desktop)");
        const win32_window_smoke_cmd = b.addRunArtifact(exe);
        win32_window_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_window_smoke_cmd.addArg("win32-window-smoke");
        win32_window_smoke_step.dependOn(&win32_window_smoke_cmd.step);

        const d3d11_present_smoke_step = b.step("d3d11-present-smoke", "Paint the Win32 window with D3D11 + DXGI (needs an interactive desktop and a D3D11 device)");
        const d3d11_present_smoke_cmd = b.addRunArtifact(exe);
        d3d11_present_smoke_cmd.step.dependOn(b.getInstallStep());
        d3d11_present_smoke_cmd.addArg("d3d11-present-smoke");
        d3d11_present_smoke_step.dependOn(&d3d11_present_smoke_cmd.step);

        const d3d11_cells_smoke_step = b.step("d3d11-cells-smoke", "Draw a cell grid with synthesized glyphs through the D3D11 cell pipeline");
        const d3d11_cells_smoke_cmd = b.addRunArtifact(exe);
        d3d11_cells_smoke_cmd.step.dependOn(b.getInstallStep());
        d3d11_cells_smoke_cmd.addArg("d3d11-cells-smoke");
        d3d11_cells_smoke_step.dependOn(&d3d11_cells_smoke_cmd.step);

        const dwrite_text_smoke_step = b.step("dwrite-text-smoke", "Render real text with DirectWrite glyphs plus synthesized box drawing");
        const dwrite_text_smoke_cmd = b.addRunArtifact(exe);
        dwrite_text_smoke_cmd.step.dependOn(b.getInstallStep());
        dwrite_text_smoke_cmd.addArg("dwrite-text-smoke");
        dwrite_text_smoke_step.dependOn(&dwrite_text_smoke_cmd.step);

        // W7.2c-1은 창이 없다 — 실제 셸을 띄우므로 `check`에는 넣지 않는다(dotfile·프롬프트 영향).
        const win32_frame_smoke_step = b.step("win32-frame-smoke", "Run a live PTY through the Windows shaper and DirectWrite rasterizer into a neutral RenderFrame");
        const win32_frame_smoke_cmd = b.addRunArtifact(exe);
        win32_frame_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_frame_smoke_cmd.addArg("win32-frame-smoke");
        win32_frame_smoke_step.dependOn(&win32_frame_smoke_cmd.step);

        const win32_terminal_smoke_step = b.step("win32-terminal-smoke", "Draw a live shell session on screen with D3D11 + DirectWrite");
        const win32_terminal_smoke_cmd = b.addRunArtifact(exe);
        win32_terminal_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_terminal_smoke_cmd.addArg("win32-terminal-smoke");
        win32_terminal_smoke_step.dependOn(&win32_terminal_smoke_cmd.step);

        const win32_clipboard_smoke_step = b.step("win32-clipboard-smoke", "Round-trip text through the OS clipboard");
        const win32_clipboard_smoke_cmd = b.addRunArtifact(exe);
        win32_clipboard_smoke_cmd.step.dependOn(b.getInstallStep());
        win32_clipboard_smoke_cmd.addArg("win32-clipboard-smoke");
        win32_clipboard_smoke_step.dependOn(&win32_clipboard_smoke_cmd.step);
    }

    var macos_app_bundle_command: ?*std.Build.Step = null;
    if (target.result.os.tag == .macos) {
        const macos_swift_target = swiftMacOSTarget(b, target.result);

        // visible window smoke는 macOS window server와 Cocoa framework가 필요하다.
        // Ubuntu CI의 기본 `zig build`가 이 플랫폼 코드를 컴파일하지 않도록
        // macOS target일 때만 opt-in build step을 만든다.
        const macos_window_smoke = b.addExecutable(.{
            .name = "maru-macos-window-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/window_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
            }),
        });
        // AppKit은 Objective-C API라서 아주 얇은 platform bridge만 Objective-C로 둔다.
        // Zig executable이 실행 시간, artifact, 실패 처리를 계속 소유하게 해 제품 구조가
        // AppKit private 타입에 묶이지 않도록 한다.
        macos_window_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/appkit_window_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_window_smoke.root_module.linkFramework("Cocoa", .{});

        const macos_window_smoke_step = b.step("macos-window-smoke", "Run the visible macOS AppKit window smoke");
        const macos_window_smoke_cmd = b.addRunArtifact(macos_window_smoke);
        macos_window_smoke_cmd.setCwd(b.path("."));
        macos_window_smoke_step.dependOn(&macos_window_smoke_cmd.step);

        // 계약 테스트는 summary schema(renderSummary/durationFromEnv)만 검증하고
        // native AppKit bridge는 호출하지 않는다. extern fn은 참조되지 않으므로
        // 이 test 바이너리는 `.m`/Cocoa 링크 없이 순수 Zig로 빌드한다. 그래야
        // "summary 포맷 변경"과 "창 생성 실패"가 toolchain 의존 없이 분리된다.
        const macos_window_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/window_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
            }),
        });

        const test_macos_window_smoke_step = b.step("test-macos-window-smoke", "Run macOS window smoke contract tests");
        const run_macos_window_smoke_tests = b.addRunArtifact(macos_window_smoke_tests);
        run_macos_window_smoke_tests.setCwd(b.path("."));
        test_macos_window_smoke_step.dependOn(&run_macos_window_smoke_tests.step);

        // Metal smoke는 AppKit 창 위에 CAMetalLayer가 실제 drawable을 present하고,
        // RendererState/GlyphFrame에서 온 atlas slot/UV/raster bytes를 제품 atlas texture
        // shader sampling까지 연결한다. 현재 입력은 실제 TerminalCore text가 아니라 CoreText
        // probe surface이지만, glyph bitmap bytes는 CoreText rasterizer 산출물이다.
        const macos_metal_smoke = b.addExecutable(.{
            .name = "maru-macos-metal-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/metal_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        macos_metal_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/appkit_metal_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_metal_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_metal_smoke.root_module.linkFramework("Cocoa", .{});
        macos_metal_smoke.root_module.linkFramework("Foundation", .{});
        macos_metal_smoke.root_module.linkFramework("CoreText", .{});
        macos_metal_smoke.root_module.linkFramework("CoreGraphics", .{});
        macos_metal_smoke.root_module.linkFramework("Metal", .{});
        macos_metal_smoke.root_module.linkFramework("QuartzCore", .{});

        // 제품 셰이더는 런타임에 컴파일된다(`newLibraryWithSource:`). 그래서 MSL 문법이 깨져도 빌드·단위
        // 테스트·Metal 계약 테스트(실제 GPU를 만들지 않는다)가 전부 통과하고 앱을 띄워야만 드러난다.
        // 이 스모크는 같은 소스를 같은 API로 컴파일하고 제품이 찾는 진입점 이름까지 확인해 그 갭만 닫는다.
        // 렌더 결과는 보지 않으므로 수 초면 끝나고 CI macOS job에 얹을 수 있다.
        const macos_shader_compile_smoke = b.addExecutable(.{
            .name = "maru-macos-shader-compile-smoke",
            .root_module = b.createModule(.{
                .target = target,
                .optimize = optimize,
                .link_libc = true,
            }),
        });
        macos_shader_compile_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/shader_compile_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_shader_compile_smoke.root_module.addIncludePath(b.path("src/platform/macos"));
        // 이 실행 파일은 `maru` 모듈을 쓰지 않으므로 위쪽에서 `maru_mod`에만 더한 SDK framework 경로 보강을
        // 상속하지 못한다(os_version_min을 박으면 Zig가 자동 탐지를 끄는 그 문제 — 파일 상단 주석 참조).
        if (macos_sdk) |sdk| {
            macos_shader_compile_smoke.root_module.addSystemFrameworkPath(.{ .cwd_relative = b.fmt("{s}/System/Library/Frameworks", .{sdk}) });
        }
        macos_shader_compile_smoke.root_module.linkFramework("Foundation", .{});
        macos_shader_compile_smoke.root_module.linkFramework("Metal", .{});
        const macos_shader_compile_smoke_step = b.step(
            "macos-shader-compile-smoke",
            "Compile every product Metal shader and assert its entry points exist",
        );
        const macos_shader_compile_smoke_cmd = b.addRunArtifact(macos_shader_compile_smoke);
        macos_shader_compile_smoke_cmd.setCwd(b.path("."));
        macos_shader_compile_smoke_step.dependOn(&macos_shader_compile_smoke_cmd.step);

        const macos_metal_smoke_step = b.step("macos-metal-smoke", "Run the visible macOS Metal product atlas sampling smoke");
        const macos_metal_smoke_cmd = b.addRunArtifact(macos_metal_smoke);
        macos_metal_smoke_cmd.setCwd(b.path("."));
        macos_metal_smoke_step.dependOn(&macos_metal_smoke_cmd.step);

        const macos_metal_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/metal_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });

        // Metal 계약 테스트도 실제 GPU를 만들지 않는다. summary schema와 duration
        // guard만 검증하므로 `.m`/Cocoa/Metal 링크 없이 빌드해 native 실패와
        // artifact 계약 변경을 분리한다.
        const test_macos_metal_smoke_step = b.step("test-macos-metal-smoke", "Run macOS Metal smoke contract tests");
        const run_macos_metal_smoke_tests = b.addRunArtifact(macos_metal_smoke_tests);
        run_macos_metal_smoke_tests.setCwd(b.path("."));
        test_macos_metal_smoke_step.dependOn(&run_macos_metal_smoke_tests.step);

        // Chrome Lab readback은 synthetic UiTree를 제품 lowering과 renderer의 오프스크린
        // screenshot pass까지 잇는다. 일반 앱 tab/workspace에 Lab을 넣지 않으며 scenario마다
        // 별도 process를 써 screenshot env cache와 artifact path를 서로 격리한다.
        const macos_chrome_lab_smoke = b.addExecutable(.{
            .name = "maru-macos-chrome-lab-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/chrome_lab_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        macos_chrome_lab_smoke.root_module.addIncludePath(b.path("src/platform/macos"));
        macos_chrome_lab_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/chrome_lab_smoke.m"),
            // dispatch_once inside the product screenshot hook is a system primitive. The app-host
            // ObjC objects disable UBSan for the same reason: instrumenting its opaque state trips
            // Zig's runtime checker before Metal gets a chance to run.
            .flags = &.{ "-fobjc-arc", "-fno-sanitize=undefined" },
        });
        macos_chrome_lab_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/maru_metal_renderer.m"),
            .flags = &.{ "-fobjc-arc", "-fno-sanitize=undefined" },
        });
        // Lab의 visual artifact도 component가 만든 text DrawList를 제품 CoreText atlas로
        // 올린 뒤 같은 Metal renderer로 읽는다. quad만 찍는 회색 fixture를 UI 증거로
        // 오인하지 않도록 CoreText bridge를 이 executable에 명시적으로 연결한다.
        macos_chrome_lab_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{ "-fobjc-arc", "-fno-sanitize=undefined" },
        });
        macos_chrome_lab_smoke.root_module.linkFramework("Foundation", .{});
        macos_chrome_lab_smoke.root_module.linkFramework("CoreText", .{});
        macos_chrome_lab_smoke.root_module.linkFramework("CoreGraphics", .{});
        macos_chrome_lab_smoke.root_module.linkFramework("Metal", .{});
        macos_chrome_lab_smoke.root_module.linkFramework("QuartzCore", .{});

        const macos_chrome_lab_smoke_step = b.step("macos-chrome-lab-smoke", "Capture deterministic Chrome Lab scenarios through the product Metal renderer");
        inline for ([_][]const u8{ "empty", "loading", "retained-list", "font-specimen", "partial-scroll", "partial-group-scroll", "scrollbar", "sticky-at-rest", "sticky-pinned", "sticky-pushed", "detail-loading", "detail-ready", "detail-stale", "detail-unavailable", "sidebar-status-strip", "editor-gutter", "editor-scrolled", "editor-font-large", "editor-hazard", "editor-wide-glyph", "editor-wrap", "editor-hscroll", "editor-folded", "editor-wrap-scrolled", "editor-wrap-stale-scroll", "editor-real-file", "editor-selection", "editor-find", "editor-diff-selection", "editor-diff", "editor-diff-scrolled", "context-menu-checked", "context-menu-unchecked", "scm-rows", "scm-history", "scm-row-hover", "scm-repo-hover", "scm-scrolled", "scm-commit-edit", "scm-small-font", "dock-over-status-bar", "file-tree-rows", "file-tree-row-hover", "file-tree-scrolled", "sort-toggle-hover", "sort-toggle-pressed" }) |scenario| {
            const run_chrome_lab = b.addRunArtifact(macos_chrome_lab_smoke);
            run_chrome_lab.setCwd(b.path("."));
            run_chrome_lab.setEnvironmentVariable("MARU_CHROME_LAB_SCENARIO", scenario);
            macos_chrome_lab_smoke_step.dependOn(&run_chrome_lab.step);
        }
        // Retained-list remains the product-state fixture. Font review uses font-specimen instead:
        // it contains deliberately distinctive ASCII primary glyphs and a Korean fallback probe,
        // so reviewers do not have to infer a face change from ordinary 8×16 card copy.
        // Each process registers exactly one bundled TTF and rejects a failed requested-family
        // match before it can write a misleading PNG.
        inline for ([_][]const u8{ "jetendard", "fira-code", "cascadia-code", "hack" }) |font| {
            const run_chrome_lab_font = b.addRunArtifact(macos_chrome_lab_smoke);
            run_chrome_lab_font.setCwd(b.path("."));
            run_chrome_lab_font.setEnvironmentVariable("MARU_CHROME_LAB_SCENARIO", "font-specimen");
            run_chrome_lab_font.setEnvironmentVariable("MARU_CHROME_LAB_FONT", font);
            macos_chrome_lab_smoke_step.dependOn(&run_chrome_lab_font.step);
        }

        const macos_chrome_lab_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/chrome_lab_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        // 계약 테스트도 Lab main과 같은 measured text 경로(`chrome.system_text`)를 컴파일한다. 그
        // 경로는 CoreText bridge 심볼을 참조하므로, 캡처 실행 파일과 **같은** ObjC 소스를 붙이지
        // 않으면 `_maru_macos_coretext_shape_chrome_text` 미정의로 링크가 깨진다.
        macos_chrome_lab_smoke_tests.root_module.addIncludePath(b.path("src/platform/macos"));
        macos_chrome_lab_smoke_tests.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{ "-fobjc-arc", "-fno-sanitize=undefined" },
        });
        macos_chrome_lab_smoke_tests.root_module.linkFramework("Foundation", .{});
        macos_chrome_lab_smoke_tests.root_module.linkFramework("CoreText", .{});
        macos_chrome_lab_smoke_tests.root_module.linkFramework("CoreGraphics", .{});

        const test_macos_chrome_lab_smoke_step = b.step("test-macos-chrome-lab-smoke", "Run Chrome Lab readback artifact contract tests");
        const run_macos_chrome_lab_smoke_tests = b.addRunArtifact(macos_chrome_lab_smoke_tests);
        run_macos_chrome_lab_smoke_tests.setCwd(b.path("."));
        test_macos_chrome_lab_smoke_step.dependOn(&run_macos_chrome_lab_smoke_tests.step);

        // App PTY Metal smoke는 headless app-pty-smoke와 visible Metal smoke를 잇는다.
        // controlled PTY command output이 SurfaceRuntime/AppWindow를 거쳐 CoreText
        // DrawList shaper와 Metal atlas shader sampling까지 도달하는지 확인한다.
        const macos_app_pty_metal_smoke = b.addExecutable(.{
            .name = "maru-macos-app-pty-metal-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/app_pty_metal_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        macos_app_pty_metal_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/appkit_metal_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_app_pty_metal_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_app_pty_metal_smoke.root_module.linkFramework("Cocoa", .{});
        macos_app_pty_metal_smoke.root_module.linkFramework("Foundation", .{});
        macos_app_pty_metal_smoke.root_module.linkFramework("CoreText", .{});
        macos_app_pty_metal_smoke.root_module.linkFramework("CoreGraphics", .{});
        macos_app_pty_metal_smoke.root_module.linkFramework("Metal", .{});
        macos_app_pty_metal_smoke.root_module.linkFramework("QuartzCore", .{});

        const macos_app_pty_metal_smoke_step = b.step("macos-app-pty-metal-smoke", "Run the visible macOS live PTY Metal smoke");
        const macos_app_pty_metal_smoke_cmd = b.addRunArtifact(macos_app_pty_metal_smoke);
        macos_app_pty_metal_smoke_cmd.setCwd(b.path("."));
        macos_app_pty_metal_smoke_step.dependOn(&macos_app_pty_metal_smoke_cmd.step);

        const macos_app_pty_interactive_metal_smoke_step = b.step("macos-app-pty-interactive-metal-smoke", "Run the visible macOS interactive shell PTY Metal smoke");
        const macos_app_pty_interactive_metal_smoke_cmd = b.addRunArtifact(macos_app_pty_metal_smoke);
        macos_app_pty_interactive_metal_smoke_cmd.setCwd(b.path("."));
        macos_app_pty_interactive_metal_smoke_cmd.setEnvironmentVariable("MARU_APP_PTY_METAL_SCENARIO", "interactive-shell");
        macos_app_pty_interactive_metal_smoke_step.dependOn(&macos_app_pty_interactive_metal_smoke_cmd.step);

        const macos_app_pty_metal_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/app_pty_metal_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });

        const test_macos_app_pty_metal_smoke_step = b.step("test-macos-app-pty-metal-smoke", "Run macOS live PTY Metal smoke contract tests");
        const run_macos_app_pty_metal_smoke_tests = b.addRunArtifact(macos_app_pty_metal_smoke_tests);
        run_macos_app_pty_metal_smoke_tests.setCwd(b.path("."));
        test_macos_app_pty_metal_smoke_step.dependOn(&run_macos_app_pty_metal_smoke_tests.step);

        // Swift host type-check는 앱을 실행하지 않고 C header import와 AppKit 타입 사용만 본다.
        // 실행 smoke와 분리해 두면 launch 실패와 Swift/Zig ABI shape 실패를 따로 볼 수 있다.
        const macos_app_host_swift_check_step = b.step("macos-app-host-swift-check", "Type-check the Swift macOS app host");
        const macos_app_host_swift_check_cmd = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-typecheck",
            "-parse-as-library",
            "-target",
            macos_swift_target,
            "-import-objc-header",
        });
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/MaruAppHost-Bridging.h"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/FilePanelTerminationPolicy.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/TerminationTiming.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/TerminationWindowPolicy.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/WebPanelHitTestGeometry.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/BrowserResultTransferRegistry.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/MermaidProtocolBridge.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/MermaidHelperProcess.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/MermaidProductTick.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/MaruAppSchemeHandler.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/AgentSessionArchiveSmokeDriver.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/SessionHostInputSourcePolicy.swift"));
        macos_app_host_swift_check_cmd.addFileArg(b.path("src/platform/macos/MaruAppHost.swift"));
        macos_app_host_swift_check_cmd.setCwd(b.path("."));
        macos_app_host_swift_check_step.dependOn(&macos_app_host_swift_check_cmd.step);

        // CoreText smoke는 창이나 GPU를 만들지 않고 macOS font stack과 CPU bitmap
        // rasterization만 검증한다. 실제 text renderer를 붙이기 전에 font
        // resolve/shaping/raster 실패와 Metal 실패를 다른 artifact로 나누기 위한
        // opt-in platform smoke다.
        const macos_coretext_smoke = b.addExecutable(.{
            .name = "maru-macos-coretext-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/coretext_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        macos_coretext_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_coretext_smoke.root_module.linkFramework("Foundation", .{});
        macos_coretext_smoke.root_module.linkFramework("CoreText", .{});
        macos_coretext_smoke.root_module.linkFramework("CoreGraphics", .{});

        const macos_coretext_smoke_step = b.step("macos-coretext-smoke", "Run the macOS CoreText font shaping/raster smoke");
        const macos_coretext_smoke_cmd = b.addRunArtifact(macos_coretext_smoke);
        macos_coretext_smoke_cmd.setCwd(b.path("."));
        macos_coretext_smoke_step.dependOn(&macos_coretext_smoke_cmd.step);

        const macos_coretext_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/coretext_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        // 대부분의 contract 테스트는 fake native 결과로 순수 Zig 로직을 검증하지만, box-drawing
        // glyph_id 정규화(#1·#2·#6)처럼 네이티브 셰이퍼(coretext_smoke.m)를 실제로 통과해야만 잡히는
        // 회귀가 있다. 그 테스트가 maru_macos_coretext_shape_draw_list extern을 부르므로 ObjC 소스와
        // 프레임워크를 링크한다(실행 파일 타깃과 동일). macOS 게이트 안이라 Linux CI에는 영향 없다.
        macos_coretext_smoke_tests.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_coretext_smoke_tests.root_module.linkFramework("Foundation", .{});
        macos_coretext_smoke_tests.root_module.linkFramework("CoreText", .{});
        macos_coretext_smoke_tests.root_module.linkFramework("CoreGraphics", .{});

        const test_macos_coretext_smoke_step = b.step("test-macos-coretext-smoke", "Run macOS CoreText smoke contract tests");
        const run_macos_coretext_smoke_tests = b.addRunArtifact(macos_coretext_smoke_tests);
        run_macos_coretext_smoke_tests.setCwd(b.path("."));
        test_macos_coretext_smoke_step.dependOn(&run_macos_coretext_smoke_tests.step);

        // Glyph texture smoke는 창을 띄우지 않고 CoreText CPU bitmap을 Metal texture로
        // 업로드한 뒤 blit readback으로 픽셀이 보존되는지 확인한다. 실제 text draw와
        // window compositing은 다음 단계로 남기고, raster와 GPU upload 실패를 분리한다.
        const macos_glyph_texture_smoke = b.addExecutable(.{
            .name = "maru-macos-glyph-texture-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/glyph_texture_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
            }),
        });
        macos_glyph_texture_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/glyph_texture_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_glyph_texture_smoke.root_module.linkFramework("Foundation", .{});
        macos_glyph_texture_smoke.root_module.linkFramework("CoreText", .{});
        macos_glyph_texture_smoke.root_module.linkFramework("CoreGraphics", .{});
        macos_glyph_texture_smoke.root_module.linkFramework("Metal", .{});

        const macos_glyph_texture_smoke_step = b.step("macos-glyph-texture-smoke", "Run the macOS CoreText-to-Metal glyph texture smoke");
        const macos_glyph_texture_smoke_cmd = b.addRunArtifact(macos_glyph_texture_smoke);
        macos_glyph_texture_smoke_cmd.setCwd(b.path("."));
        macos_glyph_texture_smoke_step.dependOn(&macos_glyph_texture_smoke_cmd.step);

        const macos_glyph_texture_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/glyph_texture_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
            }),
        });

        const test_macos_glyph_texture_smoke_step = b.step("test-macos-glyph-texture-smoke", "Run macOS glyph texture smoke contract tests");
        const run_macos_glyph_texture_smoke_tests = b.addRunArtifact(macos_glyph_texture_smoke_tests);
        run_macos_glyph_texture_smoke_tests.setCwd(b.path("."));
        test_macos_glyph_texture_smoke_step.dependOn(&run_macos_glyph_texture_smoke_tests.step);

        // Glyph text smoke는 CoreText CPU bitmap을 Metal texture로 올린 뒤 실제
        // AppKit 창의 CAMetalLayer에서 fragment shader로 샘플링한다. 제품 renderer는
        // 아니지만, texture upload와 "화면에 glyph가 그려짐" 사이의 실패 단계를 분리한다.
        const macos_glyph_text_smoke = b.addExecutable(.{
            .name = "maru-macos-glyph-text-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/glyph_text_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });
        macos_glyph_text_smoke.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/appkit_glyph_text_smoke.m"),
            .flags = &.{"-fobjc-arc"},
        });
        macos_glyph_text_smoke.root_module.linkFramework("Cocoa", .{});
        macos_glyph_text_smoke.root_module.linkFramework("CoreText", .{});
        macos_glyph_text_smoke.root_module.linkFramework("CoreGraphics", .{});
        macos_glyph_text_smoke.root_module.linkFramework("Metal", .{});
        macos_glyph_text_smoke.root_module.linkFramework("QuartzCore", .{});

        const macos_glyph_text_smoke_step = b.step("macos-glyph-text-smoke", "Run the visible macOS glyph text shader sampling smoke");
        const macos_glyph_text_smoke_cmd = b.addRunArtifact(macos_glyph_text_smoke);
        macos_glyph_text_smoke_cmd.setCwd(b.path("."));
        macos_glyph_text_smoke_step.dependOn(&macos_glyph_text_smoke_cmd.step);

        const macos_glyph_text_smoke_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/glyph_text_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                },
            }),
        });

        const test_macos_glyph_text_smoke_step = b.step("test-macos-glyph-text-smoke", "Run macOS glyph text smoke contract tests");
        const run_macos_glyph_text_smoke_tests = b.addRunArtifact(macos_glyph_text_smoke_tests);
        run_macos_glyph_text_smoke_tests.setCwd(b.path("."));
        test_macos_glyph_text_smoke_step.dependOn(&run_macos_glyph_text_smoke_tests.step);
    }

    // **중계만 따로 돌리는 스텝**(S10c). 전체 스위트는 3천 개가 넘어 한 번 도는 데 20분 넘게
    // 걸리고, 그 안에서는 변이 검사를 실무적으로 못 한다 — 이 파일의 규칙(바이트를 해석하지
    // 않는다·끝을 세 갈래로 가른다)은 변이로 재야 값이 있다.
    //
    // 이름 필터는 매치가 0개여도 "All 0 tests passed." 로 초록이라, **개수를 못박는다**
    // (같은 사고를 이 저장소가 파일 탐색기 게이트에서 겪었다).
    const cli_relay_tests = addProjectTest(b, .{
        .root_module = maru_mod,
        .filters = &.{"control_relay"},
    });
    const run_cli_relay_tests = b.addRunArtifact(cli_relay_tests);
    run_cli_relay_tests.setCwd(b.path("."));
    // 30 = 이름이 필터에 걸리는 중계 테스트 9개 + 이 모듈 그래프의 **이름 없는 test 블록** 21개
    // (필터는 이름 있는 것만 거르고 익명 블록은 늘 컴파일된다 — 파일 탐색기 게이트와 같은 셈법).
    // 숫자가 틀렸다고 나오면 먼저 **어느 테스트가 빠졌는지** 보고, 정당한 증감일 때만 갱신한다.
    run_cli_relay_tests.addArg("--maru-expect-tests=30");
    const test_cli_relay_step = b.step("test-cli-relay", "Run the `maru control --stdio` relay tests only");
    test_cli_relay_step.dependOn(&run_cli_relay_tests.step);

    const core_tests = addProjectTest(b, .{
        .root_module = maru_mod,
    });
    const run_core_tests = b.addRunArtifact(core_tests);

    // ── 크로스 타깃 **컴파일 전용** 게이트 (`zig build check-targets`) ──────────────────────────
    //
    // **왜 `zig build test -Dtarget=…`가 아닌가.** 그 명령은 컴파일 뒤 산출물을 **실행**하려 하고,
    // 외래 타깃 바이너리는 호스트에서 못 돈다 — 실측: Windows 호스트에서 `-Dtarget=x86_64-linux`는
    // 모든 컴파일이 깨끗해도 exit 1이다(`unable to execute binaries from the target`). 즉 그것을 게이트로
    // 걸면 계약이 성립하든 말든 **항상 빨갛다.** 한동안 문서가 그걸 게이트라고 적었는데, 실제로는 사람이
    // 컴파일 오류 줄만 눈으로 거른 것이었다(코드 리뷰가 잡았다).
    //
    // 그래서 여기서는 **Run을 만들지 않는다.** Compile 스텝에만 의존하면 Zig가 바이너리를 내는 데까지만
    // 가고 실행하지 않는다 — 그것이 우리가 원하는 것이다. 중립 레이어가 세 백엔드(macOS·Windows·
    // Unsupported) 모두에서 **컴파일되는지**를 CI에 Windows/macOS 러너 없이 지킨다(계약 §4).
    const check_targets_step = b.step("check-targets", "다른 OS 타깃으로 컴파일만 해 본다(실행 없음)");
    for ([_][]const u8{ "aarch64-macos", "x86_64-linux", "x86_64-windows" }) |triple| {
        const query = std.Target.Query.parse(.{ .arch_os_abi = triple }) catch @panic("bad triple");
        const cross_target = b.resolveTargetQuery(query);
        const cross_mod = b.createModule(.{
            .root_source_file = b.path("src/maru.zig"),
            .target = cross_target,
            .optimize = optimize,
            .link_libc = true,
            .imports = &.{.{ .name = "shutdown_wire_contract", .module = shutdown_wire_contract_mod }},
        });
        cross_mod.addAnonymousImport("maru_terminfo", .{ .root_source_file = b.path("terminfo/maru.terminfo") });
        cross_mod.addAnonymousImport("config_doc_md", .{ .root_source_file = b.path("docs/configuration.md") });
        const cross_tests = addProjectTest(b, .{ .root_module = cross_mod });
        // **Run이 없다** — 컴파일 산출물에만 의존한다.
        check_targets_step.dependOn(&cross_tests.step);

        // **중립 표면 전체를 강제로 분석한다**(W8.0, 계약 §2m.2). 위 `cross_mod` 만으로는
        // **테스트가 참조하는 것까지만** 분석된다 — Zig 는 함수 본문을 게으르게 보고
        // `refAllDecls` 는 비재귀다. 실측으로 그 구멍이 ADE 표면 크기였다(도크 셋의 `view`).
        //
        // **이 walker 를 `maru.zig` 에 넣지 않는다.** 넣어 봤더니 호스트 `zig build test` 에서
        // `session_dock`·`archive_detail`·`ui.button` 의 44 개가 **한 번 더** 돌았다 — 그것들은
        // 이미 `test-chrome-ui` 에서 돌고 있어서 순수한 중복이었다(적대적 검증이 잡았다).
        // 크로스 타깃 컴파일에만 필요한 것이므로 여기서만 자기 루트로 세운다.
        const surface_mod = b.createModule(.{
            .root_source_file = b.path("src/cross_target_surface.zig"),
            .target = cross_target,
            .optimize = optimize,
            .link_libc = true,
            .imports = &.{.{ .name = "shutdown_wire_contract", .module = shutdown_wire_contract_mod }},
        });
        surface_mod.addAnonymousImport("maru_terminfo", .{ .root_source_file = b.path("terminfo/maru.terminfo") });
        surface_mod.addAnonymousImport("config_doc_md", .{ .root_source_file = b.path("docs/configuration.md") });
        const surface_tests = addProjectTest(b, .{ .root_module = surface_mod });
        check_targets_step.dependOn(&surface_tests.step);

        // **`main.zig`도 반드시 넣는다.** 중립 모듈(`maru.zig`)만 컴파일하면 CLI 진입점이 빠지는데,
        // 거기가 W2의 호스트 게이트(`hostGateReason`·terminfo·`install-cli`·`maru ssh`)와 W8.5의 경로
        // 정책이 사는 자리라 타깃별로 가장 잘 깨진다. 실측으로 확인했다 — `main.zig`에 macOS 전용 타입
        // 오류를 심으면 `maru.zig`만 도는 게이트는 **통과해 버린다**(적대적 검증에서 잡았다).
        const cross_exe_mod = b.createModule(.{
            .root_source_file = b.path("src/main.zig"),
            .target = cross_target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = cross_mod },
                .{ .name = "session_host_build_options", .module = session_host_product_options.createModule() },
            },
        });
        // **테스트가 아니라 실행 파일로 컴파일한다.** 테스트 빌드는 test 블록이 참조하는 것만 분석하므로
        // `main()`과 그 아래(호스트 게이트·경로 정책)가 통째로 빠진다 — 실측: `main.zig`에 macOS 전용 타입
        // 오류를 심고 테스트 빌드로 돌리면 **통과한다.** 실행 파일은 `main`이 진입점이라 반드시 분석된다.
        const cross_exe = b.addExecutable(.{ .name = b.fmt("maru-check-{s}", .{triple}), .root_module = cross_exe_mod });
        if (cross_target.result.os.tag == .macos) {
            if (builtin.os.tag == .macos or b.sysroot != null) {
                linkSessionHostNotificationAdapter(b, cross_exe);
            } else {
                linkSessionHostNotificationCompileStub(b, cross_exe);
            }
        }
        check_targets_step.dependOn(&cross_exe.step);
    }

