        // ObjC 브리지와 framework를 링크해야 한다. Linux 빌드는 tick의 macOS 분기가
        // comptime으로 제외되어 이 심볼을 참조하지 않으므로 추가가 필요 없다.
        macos_app_host_abi_tests.root_module.addCSourceFile(.{
