            "agent hooks install into codex and record trust without touching existing entries",
            "codex 신뢰 값이 낡으면 한 번만 고치고, 되돌아오면 알린다",
            "codex 신뢰 값을 못 썼으면 «고쳤다» 고 말하지 않는다",
            "P4: 배치를 바꾸는 사건이 checkpoint dirty 를 세운다",
            "turning the agent hooks gate off removes what we installed and nothing else",
            "hook mode fills state and conversation from the event log, and only then",
            "hook mode runs exactly one source and takes over notifications",
            "훅이 받는 이름과 GUI 가 읽는 이름이 같은 파일을 가리킨다 — 제품 spawn 으로 건넌다",
            "host 가 만드는 칸과 GUI 가 읽는 칸이 같은 경로다 — 두 모듈이 같은 이름을 짓는다",
            "in-process Term 은 host 칸을 쳐다보지 않는다 — 그 자식은 GUI 가 띄웠다",
            "부재 중 쌓인 로그는 상태만 세우고 알리지 않는다 — 재접속이 옛 알림을 쏟지 않게",
            "AH7 통합: host-backed Term 의 배지와 대화 줄이 진짜 훅 커맨드에서 온다",
            "agent hooks stay out of provider files while the gate is off",
            "statusline hook is removed on startup — the wrapped original comes back and our files go",
            "statusline removal leaves someone else's statusLine alone",
            "legacy provider workspace fields are ignored across multi-window parse apply and write-new",
