        }),
    });
    // 이 정적 라이브러리는 Zig가 아니라 Swift가 최종 링크한다. Zig 0.16 JSON/float 경로가 쓰는
    // compiler-rt 보조 심볼을 archive에 포함해야 Swift linker가 별도 Zig runtime을 추측하지 않는다.
    macos_app_host_abi_lib.bundle_compiler_rt = true;
    macos_app_host_abi_lib.root_module.addIncludePath(b.path("src/platform/macos"));
    // build_options 모듈(위에서 생성)을 app host lib에도 주입 — 계약 테스트 모듈과 같은 모듈을 공유한다.
    macos_app_host_abi_lib.root_module.addImport("build_options", build_options_mod);
    if (target.result.os.tag == .macos) {
        macos_app_host_abi_lib.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/session_host_notification_route.c"),
            // Swift가 이 archive를 최종 링크하므로 Zig UBSan runtime 심볼을 요구하면 안 된다.
            // 아래 CoreText/Metal C bridge와 같은 최종-link owner 규칙이다.
            .flags = &.{"-fno-sanitize=undefined"},
        });
        // CoreText 브리지 object를 정적 라이브러리에 함께 담아, Swift 최종 링크가 .a 하나로
        // app session의 glyph rasterize 심볼을 모두 얻게 한다. CoreText/CoreGraphics
        // framework는 Swift 링크 단계에서 제공한다.
        // -iframeworkwithsysroot: framework를 sysroot 기준으로 검색해 cross-compile에서도
        // framework 헤더 내부의 angle include(Security.framework → <libDER/...>)와 availability
        // 메타데이터가 SDK 컨텍스트로 정상 해석된다. 절대 -iframework만 주면 그 헤더의 내부
        // include가 sysroot usr/include를 못 봐 'libDER/DERItem.h not found'·CGToneMapping
        // availability 에러가 난다(x86_64 cross 실측). universal(arm64+x86_64) 빌드에 필요.
        // -iwithsysroot /usr/include: framework 헤더 내부의 angle include(<libDER/DERItem.h>)가
        // sysroot의 usr/include를 검색하게 한다. cross-compile에서 Zig는 usr/include를 default
        // system include로 자동 추가하지 않아 이 명시가 필요하다.
        macos_app_host_abi_lib.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            // UBSan 계측을 끈다. 이 .a는 Zig가 아니라 swiftc가 최종 링크하므로 Zig의
            // compiler-rt(__ubsan_handle_*)가 들어오지 않아, 계측을 켜 두면 undefined
            // symbol로 링크가 실패한다.
            .flags = objc_macos_flags,
        });
        // 제품 Metal renderer(Swift Metal view가 호출)를 같은 .a에 담는다. Metal/QuartzCore
        // framework는 Swift 최종 링크에서 제공한다. 같은 이유로 UBSan을 끈다.
        macos_app_host_abi_lib.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/maru_metal_renderer.m"),
            .flags = objc_macos_flags,
        });
    }
    const install_macos_app_host_abi_lib = b.addInstallArtifact(macos_app_host_abi_lib, .{});

    const test_macos_app_host_abi_step = b.step("test-macos-app-host-abi", "Run macOS Swift/Zig app host ABI contract tests");
    // fresh-process 행도 서로 병렬 실행하면 daemon fixture와 wall-clock 성능 오라클이 다시 경쟁한다.
    // aggregate 뒤 실제 TTY, 제품 socket 두 행, teardown, CoreText cache 행 순으로 직렬화한다.
    run_macos_external_tty_fresh_tests.step.dependOn(&run_macos_app_host_abi_tests.step);
    run_macos_external_attach_fresh_tests.step.dependOn(&run_macos_external_tty_fresh_tests.step);
    run_macos_attach_resolver_fresh_tests.step.dependOn(&run_macos_external_attach_fresh_tests.step);
    run_macos_upgrade_multifd_fresh_tests.step.dependOn(&run_macos_attach_resolver_fresh_tests.step);
    run_macos_event_release_fresh_tests.step.dependOn(&run_macos_upgrade_multifd_fresh_tests.step);
    run_macos_chrome_face_cache_fresh_tests.step.dependOn(&run_macos_event_release_fresh_tests.step);
    test_macos_app_host_abi_step.dependOn(&run_macos_chrome_face_cache_fresh_tests.step);

    const macos_app_host_abi_lib_step = b.step("macos-app-host-abi-lib", "Build the Zig static library exported to the Swift macOS app host");
    macos_app_host_abi_lib_step.dependOn(&install_macos_app_host_abi_lib.step);

    if (target.result.os.tag == .macos) {
        const macos_swift_target = swiftMacOSTarget(b, target.result);

        // Smoke parent만 reset export가 있는 별도 ABI variant를 링크한다. 제품 static library에는
        // app-lifetime latch/nonce/queue를 초기화하는 symbol이 존재하지 않는다.
        const macos_mermaid_smoke_abi_lib = b.addLibrary(.{
            .name = "maru-macos-mermaid-smoke-abi",
            .linkage = .static,
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/app_host_abi.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                    .{ .name = "build_options", .module = build_options_test_mod },
                },
            }),
        });
        // smoke ABI도 Swift가 직접 링크하므로 제품 ABI와 같은 compiler-rt 소유 규칙을 따른다.
        macos_mermaid_smoke_abi_lib.bundle_compiler_rt = true;
        macos_mermaid_smoke_abi_lib.root_module.addIncludePath(b.path("src/platform/macos"));
        macos_mermaid_smoke_abi_lib.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = objc_macos_flags,
        });
        macos_mermaid_smoke_abi_lib.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/maru_metal_renderer.m"),
            .flags = objc_macos_flags,
        });

        const macos_mermaid_product_symbol_check = b.addSystemCommand(&.{
            "sh", "-eu", "-c", "if nm -gU \"$1\" | /usr/bin/grep -q 'maru_macos_mermaid_test_reset'; then echo 'error: smoke reset leaked into product ABI' >&2; exit 1; fi", "sh",
        });
        macos_mermaid_product_symbol_check.addFileArg(macos_app_host_abi_lib.getEmittedBin());

        // Swift 제품 host는 Zig compiler가 직접 만들 수 없으므로 xcrun swiftc를 build graph의
        // system command로 둔다. 대신 입력은 C header와 Zig static library로 제한해서
        // Swift가 Zig 내부 타입이나 allocator-owned storage에 묶이지 않게 한다.
        const macos_app_mkdir = b.addSystemCommand(&.{ "mkdir", "-p", "zig-out/bin" });
        macos_app_mkdir.setCwd(b.path("."));

        const macos_app_compile = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-parse-as-library",
            "-target",
            macos_swift_target,
            "-import-objc-header",
        });
        macos_app_compile.addFileArg(b.path("src/platform/macos/MaruAppHost-Bridging.h"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/FilePanelTerminationPolicy.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/TerminationTiming.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/TerminationWindowPolicy.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/WebPanelHitTestGeometry.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/BrowserResultTransferRegistry.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/MermaidProtocolBridge.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/MermaidHelperProcess.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/MermaidProductTick.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/MaruAppSchemeHandler.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/AgentSessionArchiveSmokeDriver.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/SessionHostInputSourcePolicy.swift"));
        macos_app_compile.addFileArg(b.path("src/platform/macos/MaruAppHost.swift"));
        macos_app_compile.addFileArg(macos_app_host_abi_lib.getEmittedBin());
        macos_app_compile.addArgs(&.{
            "-framework",
            "AppKit",
            // app session이 정적 라이브러리에 담긴 CoreText 브리지로 glyph를 rasterize하므로
            // 최종 링크에서 CoreText/CoreGraphics framework를 제공한다. Metal/QuartzCore는
            // 정적 라이브러리에 담긴 제품 Metal renderer가 쓴다.
            "-framework",
            "CoreText",
            "-framework",
            "CoreGraphics",
            "-framework",
            "Metal",
            "-framework",
            "QuartzCore",
            // Phase 4c: 빈 WKWebView를 pane 본문에 부착(터미널<웹뷰<오버레이 z-order). WebKit은 시스템 프레임워크라
            // 의존성 0(docs/web-panel.md §13). 콘텐츠·브리지·보안은 Phase 5.
            "-framework",
            "WebKit",
            // browser.executeScript raw expression은 page wrapper에 넣기 전에 JavaScriptCore syntax-only parser로
            // 독립 expression 경계를 검증한다(eval/Function 실행 없음).
            "-framework",
            "JavaScriptCore",
            // FP10c1: 번들 helper의 code-sign validity/Team ID를 spawn 전에 검증한다.
            "-framework",
            "Security",
            // Retina HiDPI: bare 실행파일(.app 번들 없음)에 Info.plist를 __TEXT,__info_plist
            // 섹션으로 임베드해 NSHighResolutionCapable을 켠다. 없으면 macOS가 창을 1x backing
            // store로 렌더해 window.backingScaleFactor가 1.0이 되고 Retina에서 흐려진다.
            "-Xlinker",
            "-sectcreate",
            "-Xlinker",
            "__TEXT",
            "-Xlinker",
            "__info_plist",
            "-Xlinker",
        });
        macos_app_compile.addFileArg(macos_info_plist);
        macos_app_compile.addArgs(&.{
            "-o",
            "zig-out/bin/maru-macos-app",
        });
        macos_app_compile.setCwd(b.path("."));
        macos_app_compile.step.dependOn(&macos_app_mkdir.step);
        macos_app_compile.step.dependOn(&install_macos_app_host_abi_lib.step);

        // CR6d가 SIGKILL/timeout으로 AppKit teardown을 건너뛰어도 system-global input source를
        // 원래 값으로 되돌리는 최소 실행파일이다. 일반 앱에는 진입점이 없고 opt-in harness만 호출한다.
        const session_host_input_source_restore_compile = b.addSystemCommand(&.{
            "xcrun", "swiftc", "-parse-as-library", "-target", macos_swift_target,
        });
        session_host_input_source_restore_compile.addFileArg(
            b.path("src/platform/macos/SessionHostInputSourcePolicy.swift"),
        );
        session_host_input_source_restore_compile.addFileArg(
            b.path("src/platform/macos/SessionHostInputSourceRestore.swift"),
        );
        session_host_input_source_restore_compile.addArgs(&.{
            "-o", "zig-out/bin/maru-session-host-input-source-restore",
        });
        session_host_input_source_restore_compile.setCwd(b.path("."));
        session_host_input_source_restore_compile.step.dependOn(&macos_app_mkdir.step);

        const macos_app_build_step = b.step("macos-app-build", "Build the runnable macOS Swift app host app shell");
        macos_app_build_step.dependOn(&macos_app_compile.step);

        // web/dist는 생성물이라 git에 넣지 않는다. helper smoke와 앱 bundle이 같은 결정적 asset을 소비한다.
        const file_panel_web_build = b.addSystemCommand(&.{ "bun", "run", "--cwd", "web", "web:build" });
        file_panel_web_build.setCwd(b.path("."));

        // The generated digest is compiled into the signed helper instead of trusted from a sibling
        // manifest at runtime. The helper can therefore authenticate the exact resource bytes it reads.
        const mermaid_digest_generate = b.addSystemCommand(&.{
            "bun", "run", "web/scripts/generate-mermaid-digest.ts",
        });
        mermaid_digest_generate.setCwd(b.path("."));
        mermaid_digest_generate.addFileArg(b.path("web/dist/mermaid-helper.js"));
        const mermaid_digest_swift = mermaid_digest_generate.addOutputFileArg("MermaidHelperDigest.swift");
        mermaid_digest_generate.step.dependOn(&file_panel_web_build.step);

        // FP10c1 Mermaid renderer는 앱 편집 WKWebView와 프로세스를 분리한다. parent/helper 모두 같은 Zig
        // static library codec을 링크하므로 Swift에 wire serializer가 생기지 않는다.
        const macos_mermaid_helper_compile = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-target",
            macos_swift_target,
            "-import-objc-header",
        });
        macos_mermaid_helper_compile.addFileArg(b.path("src/platform/macos/MaruAppHost-Bridging.h"));
        macos_mermaid_helper_compile.addFileArg(b.path("src/platform/macos/MermaidProtocolBridge.swift"));
        macos_mermaid_helper_compile.addFileArg(b.path("src/platform/macos/MermaidRendererPage.swift"));
        macos_mermaid_helper_compile.addFileArg(b.path("src/platform/macos/MermaidScriptLoader.swift"));
        macos_mermaid_helper_compile.addFileArg(mermaid_digest_swift);
        macos_mermaid_helper_compile.addFileArg(b.path("src/platform/macos/MaruMermaidRenderer.swift"));
        macos_mermaid_helper_compile.addFileArg(macos_app_host_abi_lib.getEmittedBin());
        macos_mermaid_helper_compile.addArgs(&.{
            "-framework", "AppKit",
            "-framework", "CoreText",
            "-framework", "CoreGraphics",
            "-framework", "Metal",
            "-framework", "QuartzCore",
            "-framework", "WebKit",
            "-framework", "JavaScriptCore",
            "-framework", "CryptoKit",
            "-o",         "zig-out/bin/maru-mermaid-renderer",
        });
        macos_mermaid_helper_compile.setCwd(b.path("."));
        macos_mermaid_helper_compile.step.dependOn(&macos_app_mkdir.step);
        macos_mermaid_helper_compile.step.dependOn(&install_macos_app_host_abi_lib.step);

        // The main app is intentionally not App Sandbox-enabled, so a raw Process child would retain its
        // ambient authority. Package/sign a distinct background app with no user-file/network-server rights.
        // WKWebView requires network.client to launch WebContent; page CSP/instrumentation proves request 0.
        const macos_mermaid_helper_bundle = b.addSystemCommand(&.{
            "sh", "-eu", "-c",
            "helper=zig-out/MaruMermaidRenderer.app; " ++
                "rm -rf \"$helper\"; " ++
                "mkdir -p \"$helper/Contents/MacOS\" \"$helper/Contents/Resources/web\"; " ++
                "cp zig-out/bin/maru-mermaid-renderer \"$helper/Contents/MacOS/maru-mermaid-renderer\"; " ++
                "cp src/platform/macos/MaruMermaidRenderer-Info.plist \"$helper/Contents/Info.plist\"; " ++
                "cp web/dist/mermaid-helper.js \"$helper/Contents/Resources/web/mermaid-helper.js\"; " ++
                "printf 'APPL????' > \"$helper/Contents/PkgInfo\"; " ++
                "codesign --force --sign - --entitlements src/platform/macos/MaruMermaidRenderer.entitlements \"$helper\"; " ++
                "codesign --verify --strict \"$helper\"; " ++
                "codesign -d --entitlements :- \"$helper\" > zig-out/MaruMermaidRenderer.entitlements.plist 2>/dev/null; " ++
                "test \"$(/usr/libexec/PlistBuddy -c 'Print :com.apple.security.app-sandbox' zig-out/MaruMermaidRenderer.entitlements.plist)\" = true; " ++
                "test \"$(/usr/libexec/PlistBuddy -c 'Print :com.apple.security.network.client' zig-out/MaruMermaidRenderer.entitlements.plist)\" = true; " ++
                "! /usr/libexec/PlistBuddy -c 'Print :com.apple.security.network.server' zig-out/MaruMermaidRenderer.entitlements.plist >/dev/null 2>&1",
        });
        macos_mermaid_helper_bundle.setCwd(b.path("."));
        macos_mermaid_helper_bundle.step.dependOn(&macos_mermaid_helper_compile.step);
        macos_mermaid_helper_bundle.step.dependOn(&file_panel_web_build.step);

        const macos_mermaid_helper_build_step = b.step("macos-mermaid-helper-build", "Build the isolated Mermaid renderer helper");
        macos_mermaid_helper_build_step.dependOn(&macos_mermaid_helper_bundle.step);

        // Test-only: a valid seal whose resource disagrees with the executable's embedded digest proves
        // exit 12 is permanent. Keep this damaged app out of ordinary helper/product bundle steps.
        const macos_mermaid_digest_mismatch_fixture = b.addSystemCommand(&.{
            "sh", "-eu", "-c",
            "helper=zig-out/MaruMermaidRenderer.app; " ++
                "mismatch=zig-out/maru-macos-mermaid-helper-smoke/fixtures/MaruMermaidRendererDigestMismatch.app; " ++
                "mkdir -p zig-out/maru-macos-mermaid-helper-smoke/fixtures; " ++
                "rm -rf \"$mismatch\"; cp -R \"$helper\" \"$mismatch\"; " ++
                "printf '\n// digest mismatch fixture\n' >> \"$mismatch/Contents/Resources/web/mermaid-helper.js\"; " ++
                "codesign --force --sign - --entitlements src/platform/macos/MaruMermaidRenderer.entitlements \"$mismatch\"",
        });
        macos_mermaid_digest_mismatch_fixture.setCwd(b.path("."));
        macos_mermaid_digest_mismatch_fixture.step.dependOn(&macos_mermaid_helper_bundle.step);

        const macos_mermaid_smoke_compile = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-target",
            macos_swift_target,
            "-import-objc-header",
        });
        macos_mermaid_smoke_compile.addFileArg(b.path("tests/macos_mermaid_helper_smoke.h"));
        macos_mermaid_smoke_compile.addFileArg(b.path("src/platform/macos/MermaidProtocolBridge.swift"));
        macos_mermaid_smoke_compile.addFileArg(b.path("src/platform/macos/MermaidRendererPage.swift"));
        macos_mermaid_smoke_compile.addFileArg(b.path("src/platform/macos/MermaidScriptLoader.swift"));
        macos_mermaid_smoke_compile.addFileArg(mermaid_digest_swift);
        macos_mermaid_smoke_compile.addFileArg(b.path("src/platform/macos/MermaidHelperProcess.swift"));
        macos_mermaid_smoke_compile.addFileArg(b.path("src/platform/macos/MermaidProductTick.swift"));
        macos_mermaid_smoke_compile.addFileArg(b.path("tests/macos_mermaid_helper_smoke.swift"));
        macos_mermaid_smoke_compile.addFileArg(macos_mermaid_smoke_abi_lib.getEmittedBin());
        macos_mermaid_smoke_compile.addArgs(&.{
            "-framework", "AppKit",
            "-framework", "CoreText",
            "-framework", "CoreGraphics",
            "-framework", "Metal",
            "-framework", "QuartzCore",
            "-framework", "WebKit",
            "-framework", "JavaScriptCore",
            "-framework", "Security",
            "-framework", "CryptoKit",
            "-o",         "zig-out/bin/maru-mermaid-helper-smoke",
        });
        macos_mermaid_smoke_compile.setCwd(b.path("."));
        macos_mermaid_smoke_compile.step.dependOn(&macos_app_mkdir.step);
        macos_mermaid_smoke_compile.step.dependOn(&macos_mermaid_smoke_abi_lib.step);
        macos_mermaid_smoke_compile.step.dependOn(&macos_mermaid_product_symbol_check.step);

        const macos_mermaid_smoke_run = b.addSystemCommand(&.{"./zig-out/bin/maru-mermaid-helper-smoke"});
        macos_mermaid_smoke_run.setCwd(b.path("."));
        macos_mermaid_smoke_run.setEnvironmentVariable("MARU_MERMAID_HELPER_PATH", b.pathFromRoot("zig-out/MaruMermaidRenderer.app/Contents/MacOS/maru-mermaid-renderer"));
        macos_mermaid_smoke_run.setEnvironmentVariable("MARU_MERMAID_DIGEST_MISMATCH_HELPER_PATH", b.pathFromRoot("zig-out/maru-macos-mermaid-helper-smoke/fixtures/MaruMermaidRendererDigestMismatch.app/Contents/MacOS/maru-mermaid-renderer"));
        macos_mermaid_smoke_run.setEnvironmentVariable("MARU_MERMAID_RENDERER_SCRIPT", b.pathFromRoot("web/dist/mermaid-helper.js"));
        macos_mermaid_smoke_run.step.dependOn(&macos_mermaid_helper_bundle.step);
        macos_mermaid_smoke_run.step.dependOn(&macos_mermaid_digest_mismatch_fixture.step);
        macos_mermaid_smoke_run.step.dependOn(&macos_mermaid_smoke_compile.step);
        macos_mermaid_smoke_run.step.dependOn(&file_panel_web_build.step);
        const perf_validate_exe = b.addExecutable(.{
            .name = "maru-perf-validate",
            .root_module = b.createModule(.{
                .root_source_file = b.path("tools/perf/validate_json_artifact.zig"),
                .target = target,
                .optimize = optimize,
            }),
        });

        // 이전 gate는 앵커 없는 grep 체인이라 "ticks":10000이 1000을 부분 문자열로 포함해 통과했다
        // (예산 10배 악화 false-green). 이제 tools/perf/validate_json_artifact.zig가 JSON을 실제로
        // 파싱해 exact/bound로 판정한다. has_side_effects=true라 매 실행 새 artifact를 재검증한다.
        const macos_mermaid_smoke_assert = b.addRunArtifact(perf_validate_exe);
        macos_mermaid_smoke_assert.addArgs(&.{
            "mermaid-helper-summary",
            "zig-out/maru-macos-mermaid-helper-smoke/mermaid-helper.summary.json",
        });
        macos_mermaid_smoke_assert.setCwd(b.path("."));
        macos_mermaid_smoke_assert.has_side_effects = true;
        macos_mermaid_smoke_assert.step.dependOn(&macos_mermaid_smoke_run.step);
        const macos_mermaid_helper_smoke_step = b.step("macos-mermaid-helper-smoke", "Run the isolated Mermaid helper lifecycle smoke");
        macos_mermaid_helper_smoke_step.dependOn(&macos_mermaid_smoke_assert.step);

        // ── E0.5A: 제품 WKWebView editor 게이트(docs/editor-surface-tooling.md §7.4).
        // 하니스 asset root는 제품 dist와 분리해 스모크 전용으로 만든다 — 검증 경로(스킴 핸들러·CSP·WKWebView)는
        // 제품 그대로이고 제품 자산 집합은 건드리지 않는다.
        const macos_editor_smoke_assets = b.addSystemCommand(&.{
            "bun",                           "run",
            "--cwd",                         "web",
            "scripts/build-editor-smoke.ts", "../zig-out/maru-macos-editor-smoke/assets",
        });
        macos_editor_smoke_assets.setCwd(b.path("."));
        macos_editor_smoke_assets.has_side_effects = true;

        const macos_editor_smoke_compile = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-target",
            macos_swift_target,
            "-import-objc-header",
        });
        macos_editor_smoke_compile.addFileArg(b.path("src/platform/macos/MaruAppHost-Bridging.h"));
        macos_editor_smoke_compile.addFileArg(b.path("src/platform/macos/MaruAppSchemeHandler.swift"));
        macos_editor_smoke_compile.addFileArg(b.path("tests/macos_editor_smoke.swift"));
        macos_editor_smoke_compile.addFileArg(macos_app_host_abi_lib.getEmittedBin());
        macos_editor_smoke_compile.addArgs(&.{
            "-framework", "AppKit",
            "-framework", "CoreText",
            "-framework", "CoreGraphics",
            "-framework", "Metal",
            "-framework", "QuartzCore",
            "-framework", "WebKit",
            "-framework", "JavaScriptCore",
            "-framework", "Security",
            "-o",         "zig-out/bin/maru-macos-editor-smoke",
        });
        macos_editor_smoke_compile.setCwd(b.path("."));
        macos_editor_smoke_compile.step.dependOn(&macos_app_mkdir.step);
        macos_editor_smoke_compile.step.dependOn(&macos_app_host_abi_lib.step);

        const macos_editor_smoke_run = b.addSystemCommand(&.{"./zig-out/bin/maru-macos-editor-smoke"});
        macos_editor_smoke_run.setCwd(b.path("."));
        macos_editor_smoke_run.setEnvironmentVariable("MARU_WEB_APP_ROOT", b.pathFromRoot("zig-out/maru-macos-editor-smoke/assets"));
        macos_editor_smoke_run.setEnvironmentVariable("MARU_EDITOR_SMOKE_OUT", b.pathFromRoot("zig-out/maru-macos-editor-smoke"));
        macos_editor_smoke_run.has_side_effects = true;
        macos_editor_smoke_run.step.dependOn(&macos_editor_smoke_compile.step);
        macos_editor_smoke_run.step.dependOn(&macos_editor_smoke_assets.step);

        const macos_editor_smoke_step = b.step("test-macos-editor-smoke", "Assert the MergeView product WKWebView gate");
        macos_editor_smoke_step.dependOn(&macos_editor_smoke_run.step);

        // 눈으로 볼 때만 창을 띄운다(기본은 accessory라 CI에서 창이 뜨지 않는다).
        const macos_editor_smoke_display = b.addSystemCommand(&.{"./zig-out/bin/maru-macos-editor-smoke"});
        macos_editor_smoke_display.setCwd(b.path("."));
        macos_editor_smoke_display.setEnvironmentVariable("MARU_WEB_APP_ROOT", b.pathFromRoot("zig-out/maru-macos-editor-smoke/assets"));
        macos_editor_smoke_display.setEnvironmentVariable("MARU_EDITOR_SMOKE_OUT", b.pathFromRoot("zig-out/maru-macos-editor-smoke"));
        macos_editor_smoke_display.setEnvironmentVariable("MARU_EDITOR_SMOKE_DISPLAY", "1");
        macos_editor_smoke_display.has_side_effects = true;
        macos_editor_smoke_display.step.dependOn(&macos_editor_smoke_compile.step);
        macos_editor_smoke_display.step.dependOn(&macos_editor_smoke_assets.step);
        const macos_editor_smoke_display_step = b.step("macos-editor-smoke", "Run the MergeView WKWebView gate with a visible window");
        macos_editor_smoke_display_step.dependOn(&macos_editor_smoke_display.step);

        const macos_mermaid_perf_validate = b.addRunArtifact(perf_validate_exe);
        macos_mermaid_perf_validate.addArgs(&.{
            "mermaid-macos",
            "tests/artifacts/perf/mermaid-macos.json",
        });
        macos_mermaid_perf_validate.setCwd(b.path("."));
        macos_mermaid_perf_validate.has_side_effects = true;
        macos_mermaid_perf_validate.step.dependOn(&macos_mermaid_smoke_assert.step);

        // JSON 예산과 별개 축: 공용 tick 파일에 FS·WebView·process·pipe·sleep·blocking-wait API가
        // 새로 유입되면 실패시키는 source-policy gate(operation-site 계측을 tick에서 배제).
        const macos_mermaid_source_policy = b.addSystemCommand(&.{
            "sh", "-eu", "-c",
            "if /usr/bin/grep -En 'FileManager|WKWebView|Process\\(|Pipe\\(|sleep\\(|waitUntilExit|Data\\(contentsOf:|write\\(to:' src/platform/macos/MermaidProductTick.swift; then " ++
                "echo 'forbidden capability in MermaidProductTick.swift' >&2; exit 1; fi",
        });
        macos_mermaid_source_policy.setCwd(b.path("."));

        const macos_mermaid_perf_step = b.step("macos-mermaid-perf", "Run the native Mermaid performance artifact gate");
        macos_mermaid_perf_step.dependOn(&macos_mermaid_perf_validate.step);
        macos_mermaid_perf_step.dependOn(&macos_mermaid_source_policy.step);

        // bare 터미널 실행파일은 HiDPI(NSHighResolutionCapable)를 신뢰성 있게 못 켠다. 정식
        // .app 번들을 만들고 그 안의 바이너리를 직접 실행하면, AppKit이 실행파일 경로에서
        // Contents/Info.plist를 찾아 HiDPI를 켜고(Retina에서 또렷), open과 달리 CWD가 유지돼
        // summary 상대 경로 기록도 정상 동작한다.
        const macos_app_bundle = b.addSystemCommand(&.{
            "sh", "-eu", "-c",
            // set -e로 어느 단계든 실패하면 즉시 멈춘다. 폰트가 없는 clean checkout에서 glob이
            // 빈 채 cp가 조용히 실패하지 않도록, 번들 전에 .ttf 존재를 명시적으로 확인하고 명확한
            // 에러를 낸다.
            "ttfs=$(ls assets/fonts/*/*.ttf 2>/dev/null) || true; " ++
                "[ -n \"$ttfs\" ] || { echo 'error: no .ttf under assets/fonts/*/ (font assets missing)' >&2; exit 1; }; " ++
                // 기본 폰트(JetBrains Mono)는 항상 있어야 한다(config 기본값 theme.zig). 누락이면 self-contained 보장이 깨진다.
                "[ -f assets/fonts/JetBrainsMono/JetBrainsMono-Regular.ttf ] || { echo 'error: default font assets/fonts/JetBrainsMono missing' >&2; exit 1; }; " ++
                "rm -rf zig-out/Maru.app; " ++
                "mkdir -p zig-out/Maru.app/Contents/MacOS zig-out/Maru.app/Contents/Helpers zig-out/Maru.app/Contents/Resources/Fonts; " ++
                "cp zig-out/bin/maru-macos-app zig-out/Maru.app/Contents/MacOS/maru-macos-app; " ++
                "cp -R zig-out/MaruMermaidRenderer.app zig-out/Maru.app/Contents/Helpers/MaruMermaidRenderer.app; " ++
                // 형제 `maru` CLI도 번들에 넣는다 — 커맨드 팝업 "Install CLI"가 GUI 바이너리 옆 형제 maru를
                // ~/.local/bin에 symlink하므로, 번들에 없으면 "maru CLI 바이너리를 찾지 못했습니다"로 실패한다.
                "cp zig-out/bin/maru zig-out/Maru.app/Contents/MacOS/maru; " ++
                "cp \"$1\" zig-out/Maru.app/Contents/Info.plist; " ++
                // 모든 폰트 패밀리(assets/fonts/<Family>/)의 .ttf를 Fonts/에 평평하게 복사한다 — ATSApplicationFontsPath가
                // 그 디렉터리를 스캔해 전부 자동 등록하므로 사용자는 config의 font.family에 패밀리명만 적으면 된다.
                // 라이선스(OFL.txt·LICENSE.*)는 평평화 시 충돌하지 않게 패밀리명 프리픽스로 동봉한다(재배포 의무).
                // 새 패밀리는 디렉터리만 추가하면 자동 포함된다(이 build.zig 수정 불필요).
                "for d in assets/fonts/*/; do fam=$(basename \"$d\"); " ++
                // .ttf 없는 디렉터리는 폰트 패밀리가 아니므로 건너뛴다(폰트 자산만 처리). glob 미매치면 $1=리터럴 패턴.
                "set -- \"$d\"*.ttf; [ -e \"$1\" ] || continue; " ++
                // .ttf 복사 — 실패(권한/IO)하면 set -e로 빌드 중단(빈/불완전 Fonts 번들로 조용히 출하 방지, code-review).
                "cp \"$d\"*.ttf zig-out/Maru.app/Contents/Resources/Fonts/; " ++
                // 라이선스(재배포 의무)는 패밀리명 프리픽스로 동봉하고, .ttf가 있는데 라이선스가 하나도 없으면 빌드를
                // 실패시킨다 — '번들 폰트는 라이선스 동봉' 보장(code-review: best-effort로 새 폰트가 무-라이선스 출하되던 구멍).
                "lic_found=0; for lic in \"$d\"OFL.txt \"$d\"LICENSE.md \"$d\"LICENSE.txt; do " ++
                "if [ -f \"$lic\" ]; then cp \"$lic\" \"zig-out/Maru.app/Contents/Resources/Fonts/$fam-$(basename \"$lic\")\"; lic_found=1; fi; " ++
                "done; " ++
                "[ \"$lic_found\" = 1 ] || { echo \"error: font family $fam has .ttf but no license (OFL.txt/LICENSE.md/LICENSE.txt) — 재배포 의무\" >&2; exit 1; }; " ++
                "done; " ++
                // FP4: zntc가 만든 실 file-panel bundle(index/render HTML·SRI bundle·CSS)을 Resources/web/에 복사한다.
                // 스킴 핸들러가 Bundle.main.resourceURL/web 아래만 서빙한다(경로 샌드박스·realpath 탈출 방어=Zig 정책).
                "mkdir -p zig-out/Maru.app/Contents/Resources/web; " ++
                // scheme same-fd reader의 flat-only closed-set과 build output을 일치시킨다. 새 nested asset은 조용히
                // 번들된 뒤 404가 되지 않고 여기서 즉시 실패하며, 채택하려면 descriptor component-walk 설계를 먼저 한다.
                "[ -z \"$(find web/dist -mindepth 1 -type d -print -quit)\" ] || { echo 'error: web/dist must remain flat for maru-app scheme safety' >&2; exit 1; }; " ++
                "for asset in web/dist/*; do " ++
                "[ \"$(basename \"$asset\")\" = mermaid-helper.js ] && continue; " ++
                "cp \"$asset\" zig-out/Maru.app/Contents/Resources/web/; done; " ++
                "[ ! -e zig-out/Maru.app/Contents/Resources/web/mermaid-helper.js ] || { echo 'error: helper-only Mermaid runtime leaked into main app resources' >&2; exit 1; }; " ++
                "[ ! -e zig-out/Maru.app/Contents/Helpers/MaruMermaidRendererDigestMismatch.app ] || { echo 'error: test-only digest mismatch helper leaked into product app' >&2; exit 1; }; " ++
                "cmp web/dist/mermaid-helper.js zig-out/Maru.app/Contents/Helpers/MaruMermaidRenderer.app/Contents/Resources/web/mermaid-helper.js; " ++
                "[ \"$(find zig-out/Maru.app -name mermaid-helper.js -type f | wc -l | tr -d ' ')\" = 1 ] || { echo 'error: Mermaid runtime must have exactly one nested-helper copy' >&2; exit 1; }; " ++
                "printf 'APPL????' > zig-out/Maru.app/Contents/PkgInfo; " ++
                // 개발/CI bundle도 release와 같은 inside-out 순서를 검증한다. ad-hoc 서명이라 비밀/인증서는 필요 없다.
                "codesign --force --sign - --entitlements src/platform/macos/MaruMermaidRenderer.entitlements zig-out/Maru.app/Contents/Helpers/MaruMermaidRenderer.app; " ++
                "codesign --force --sign - zig-out/Maru.app/Contents/MacOS/maru; " ++
                "codesign --force --sign - zig-out/Maru.app/Contents/MacOS/maru-macos-app; " ++
                "codesign --force --sign - zig-out/Maru.app; " ++
                "codesign --verify --strict --deep zig-out/Maru.app",
        });
        // `sh -c` 뒤 첫 인자는 $0이므로 label을 하나 두고 generated plist를 $1로 전달한다.
        macos_app_bundle.addArg("maru-app-bundle");
        macos_app_bundle.addFileArg(macos_info_plist);
        macos_app_bundle.setCwd(b.path("."));
        macos_app_bundle.step.dependOn(&macos_app_compile.step);
        macos_app_bundle.step.dependOn(&macos_mermaid_helper_bundle.step);
        // web/dist·폰트 같은 입력은 zig build가 추적하는 인자가 아니라, side effect를 선언하지 않으면
        // "인자가 그대로다"라는 이유로 이 스텝이 통째로 스킵된다. 그러면 web을 고치고 앱을 빌드해도 번들 안
        // Resources/web은 옛 bundle.js로 남아, 제품이 조용히 구버전 웹앱을 실행한다(실제로 겪었다).
        macos_app_bundle.has_side_effects = true;
        // `macos-app-build`는 이름 그대로 **실행 가능한** 앱을 만들어야 한다. 컴파일만 걸어 두면 이 step이
        // 성공해도 zig-out/Maru.app은 옛 번들 그대로라, 그걸 열어 본 사람은 자기 변경이 사라졌다고 여긴다
        // (실제로 겪었다 — web을 고치고 이 step을 돌린 뒤 구버전 웹앱이 뜨는 앱을 열었다).
        macos_app_build_step.dependOn(&macos_app_bundle.step);
        macos_app_bundle.step.dependOn(&file_panel_web_build.step);
        macos_app_bundle.step.dependOn(b.getInstallStep()); // zig-out/bin/maru(CLI) 빌드·설치 보장 — 번들 cp의 선행조건

        const macos_app_bundle_step = b.step("macos-app-bundle", "Package the macOS app shell as a HiDPI .app bundle");
        macos_app_bundle_step.dependOn(&macos_app_bundle.step);
        macos_app_bundle_command = &macos_app_bundle.step;

        // macos-dmg: 서명·공증·staple까지 끝낸 배포용 .dmg를 한 번에 만든다.
        // 비밀값(앱 전용 암호)은 build.zig·리포에 절대 두지 않는다. 공증 자격증명은 notarytool
        // 키체인 프로파일(기본 "maru-notary")에 미리 저장해 두고 이름만 참조한다. 서명 인증서
        // 이름과 팀ID는 공개 정보라 옵션 기본값으로 둔다. 둘 다 -D 옵션으로 덮어쓸 수 있다.
        //   사전 1회: xcrun notarytool store-credentials maru-notary \
        //               --apple-id "$APPLE_ID" --team-id "$APPLE_TEAM_ID" \
        //               --password "$APPLE_APP_SPECIFIC_PASSWORD"
        // arm64 단일 빌드이므로 산출물 이름에 -arm64를 박는다. 버전은 빌드된 번들의
        // Info.plist(CFBundleShortVersionString)에서 읽어 파일명과 1:1로 맞춘다.
        const macos_sign_identity = b.option(
            []const u8,
            "macos-sign-identity",
            "codesign에 쓸 Developer ID Application 인증서 이름(키체인에서 조회)",
        ) orelse
            // 서명 주체(조직명·Team ID)는 저장소에 두지 않는다 — 소스에 박으면 공개 저장소에서 조직
            // 식별자가 그대로 노출되고, 포크한 사람이 남의 인증서 이름으로 빌드하려다 실패한다.
            // 릴리스 워크플로는 secret에서, 로컬은 `-Dmacos-sign-identity=`로 준다(스크립트 경로는
            // `MARU_SIGN_IDENTITY` 환경변수도 받는다). 키체인에 Developer ID 인증서가 하나면 이 접두사만으로
            // codesign이 찾는다.
            "Developer ID Application";
        const macos_notary_profile = b.option(
            []const u8,
            "macos-notary-profile",
            "notarytool 키체인 프로파일 이름(store-credentials로 미리 저장)",
        ) orelse "maru-notary";

        const macos_dmg = b.addSystemCommand(&.{
            "sh", "-eu", "-c",
            // 인증서 이름/프로파일명은 환경변수로 넘겨 셸 escape 문제를 피한다(아래 setEnvironmentVariable).
            // set -eu라 어느 단계든 실패하면 즉시 멈춘다. notarytool submit --wait는 공증 완료까지
            // 블록하고, staple로 티켓을 dmg에 부착해 오프라인에서도 Gatekeeper를 통과하게 한다.
            ": \"${MARU_SIGN_IDENTITY:?set -Dmacos-sign-identity}\"; " ++
                ": \"${MARU_NOTARY_PROFILE:?set -Dmacos-notary-profile}\"; " ++
                "[ -d zig-out/Maru.app ] || { echo 'error: zig-out/Maru.app missing (run macos-app-bundle first)' >&2; exit 1; }; " ++
                "echo '==> codesign app (Developer ID, hardened runtime, timestamp)'; " ++
                // 중첩 바이너리(형제 maru CLI)를 먼저 개별 서명한다(inside-out) — 번들 서명은 main executable만 봉인하므로
                // 추가 실행파일은 따로 서명해야 hardened runtime 공증을 통과한다.
                "codesign --force --options runtime --timestamp --entitlements src/platform/macos/MaruMermaidRenderer.entitlements --sign \"$MARU_SIGN_IDENTITY\" zig-out/Maru.app/Contents/Helpers/MaruMermaidRenderer.app; " ++
                "codesign --force --options runtime --timestamp --sign \"$MARU_SIGN_IDENTITY\" zig-out/Maru.app/Contents/MacOS/maru; " ++
                "codesign --force --options runtime --timestamp --sign \"$MARU_SIGN_IDENTITY\" zig-out/Maru.app; " ++
                "codesign --verify --strict --deep zig-out/Maru.app; " ++
                "version=$(/usr/libexec/PlistBuddy -c \"Print :CFBundleShortVersionString\" zig-out/Maru.app/Contents/Info.plist); " ++
                "rm -rf dist/dmg-staging; mkdir -p dist/dmg-staging; " ++
                // .app 자체를 먼저 공증 + staple한다 — dmg에만 staple하면 .app엔 티켓이 없어, 다른 맥(특히 오프라인·
                // Gatekeeper 공증 조회 실패 환경)에서 dmg로 연 .app이 "손상된 파일"로 거부된다. .app을 zip으로 묶어
                // notarytool에 제출하고, 발급된 티켓을 staple로 .app에 부착한 뒤 dmg에 담는다(아래 ditto).
                "echo '==> notarize app + staple (.app 자체에 티켓 부착 — 오프라인/타 맥 손상 방지)'; " ++
                "ditto -c -k --keepParent zig-out/Maru.app dist/Maru-app-notarize.zip; " ++
                "xcrun notarytool submit dist/Maru-app-notarize.zip --keychain-profile \"$MARU_NOTARY_PROFILE\" --wait; " ++
                "xcrun stapler staple zig-out/Maru.app; " ++
                "xcrun stapler validate zig-out/Maru.app; " ++
                "rm -f dist/Maru-app-notarize.zip; " ++
                // 티켓이 박힌 .app을 dmg 스테이징으로 복사한다(이제 .app에 공증 티켓 포함).
                "ditto zig-out/Maru.app dist/dmg-staging/Maru.app; " ++
                "ln -s /Applications dist/dmg-staging/Applications; " ++
                "dmg=\"dist/Maru-${version}-arm64.dmg\"; " ++
                "rm -f \"$dmg\"; " ++
                "echo \"==> create dmg: $dmg\"; " ++
                // 이전 빌드/검증에서 dmg를 마운트(/Volumes/Maru)한 뒤 detach가 실패하면, 같은 볼륨명으로 hdiutil
                // create가 "could not access /Volumes/Maru ... 작업이 허용되지 않음"으로 막힌다. 생성 직전 강제
                // detach해 빌드를 idempotent하게 만든다(마운트가 없으면 실패를 무시 — set -eu에 걸리지 않게 || true).
                "hdiutil detach /Volumes/Maru -force >/dev/null 2>&1 || true; " ++
                "hdiutil create -volname Maru -srcfolder dist/dmg-staging -ov -format UDZO \"$dmg\"; " ++
                "rm -rf dist/dmg-staging; " ++
                "codesign --force --timestamp --sign \"$MARU_SIGN_IDENTITY\" \"$dmg\"; " ++
                "echo '==> notarize (submit + wait) via keychain profile'; " ++
                "xcrun notarytool submit \"$dmg\" --keychain-profile \"$MARU_NOTARY_PROFILE\" --wait; " ++
                "xcrun stapler staple \"$dmg\"; " ++
                "spctl -a -t open --context context:primary-signature -v \"$dmg\"; " ++
                "echo \"==> done: $dmg\"",
        });
        macos_dmg.setEnvironmentVariable("MARU_SIGN_IDENTITY", macos_sign_identity);
        macos_dmg.setEnvironmentVariable("MARU_NOTARY_PROFILE", macos_notary_profile);
        macos_dmg.setCwd(b.path("."));
