        // 키가 창 상태를 바꿔 그쪽 단언을 깨뜨린다(실제로 한 번 뒤집혔다).
        const macos_scrollbar_smoke_step = b.step("macos-scrollbar-smoke", "Run the macOS file tree scrollbar drag AppKit E2E");
