        // The fixture launches AppKit processes and rewrites isolated HOME/capture artifacts.
        // Declaring no side effects lets `zig build` reuse an old successful step, silently
        // leaving stale screenshots and summary assertions after the smoke driver changes.
        macos_agent_session_archive_smoke.has_side_effects = true;
        macos_agent_session_archive_smoke.step.dependOn(&macos_app_bundle.step);
        macos_agent_session_archive_smoke_step.dependOn(&macos_agent_session_archive_smoke.step);

        const macos_browser_bounded_smoke_step = b.step("macos-browser-bounded-smoke", "Run and assert the bounded browser.executeScript WKWebView/socket smoke");
        const macos_browser_bounded_smoke = b.addSystemCommand(&.{ "sh", "tools/test-macos-browser-bounded-smoke.sh" });
        macos_browser_bounded_smoke.setCwd(b.path("."));
        macos_browser_bounded_smoke.setEnvironmentVariable("MARU_WEB_APP_ROOT", b.pathFromRoot("web/dist"));
        macos_browser_bounded_smoke.step.dependOn(&macos_app_compile.step);
        macos_browser_bounded_smoke.step.dependOn(&file_panel_web_build.step);
        macos_browser_bounded_smoke_step.dependOn(&macos_browser_bounded_smoke.step);
    }

    // L4 어댑터(`src/platform/macos/**`)와 POSIX 전제 CLI(`src/main.zig`)는 **타깃별 재작성 대상**이라 다른 OS에서
    // 컴파일되지 않는 것이 정상이다([layering-and-portability.md] §2 — L4는 "타깃별 신규"). 그런데 그 테스트가 기본
    // `test` 그래프에 무조건 걸려 있으면 macOS 밖에서는 **중립 레이어(L1~L3)의 회귀를 볼 방법이 없다** — 빌드가
    // L4에서 먼저 죽어 중립 테스트까지 못 간다. 그래서 L4 테스트만 macOS에서 걸고, 중립 테스트는 모든 호스트에서
    // 돌린다. 실측(Windows): 이 게이트로 `zig build test`가 중립 361개를 돌린다(게이트 전에는 0개 — 컴파일 실패).
    const macos_host_tests = target.result.os.tag == .macos;

    const test_step = b.step("test", "Run all Zig tests");
    test_step.dependOn(&run_core_tests.step);

    // **파일 트리 백엔드는 모든 호스트에서 테스트한다**(W8.1, 계약 §2m). 이 파일은
    // `src/platform/macos/` 에 있지만 macOS 프레임워크를 하나도 안 쓴다 — 순수 Zig + std 이고
    // 갈리는 것은 리프 열기 한 자리(`openLeafNoFollow`)뿐이다. 그런데 테스트가 `app_session` 모듈에
    // 실려 있어 **macOS 호스트에서만 돌았다** — Windows 에서 그 갈래를 고쳐도 아무도 안 밟는다.
    //
    // 그래서 이 파일만 도는 산출물을 따로 세워 `test` 에 매단다. macOS 에서는 `app_session` 경로와
    // 중복이지만(같은 테스트가 두 번 돈다) 그 비용이 "Windows 갈래가 검증 없이 남는 것" 보다 싸다.
    // 파일 위치가 `platform/macos/` 인 것은 이제 이름과 안 맞는다 — 옮기는 것은 소비자가 생기는
    // W8.2 와 함께 볼 일이다.
    const file_tree_backend_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/platform/macos/file_tree_backend.zig"),
            .target = target,
            .optimize = optimize,
            .link_libc = true,
            .imports = &.{.{ .name = "maru", .module = maru_mod }},
        }),
    });
    test_step.dependOn(&b.addRunArtifact(file_tree_backend_tests).step);

    // Windows 캡처 러너. **Windows 호스트에서만 건다** — `kernel32` 를 직접 부르므로 다른 호스트에서는
    // 링크할 심볼이 없다. 테스트가 전부 `builtin.os.tag != .windows` 에서 skip 이라 다른 호스트에
    // 걸어 봐야 아무것도 안 재고 링크만 깨진다. 그 대신 **시끄럽게 건너뛴다**.
    if (target.result.os.tag == .windows) {
        const win32_process_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                // **루트는 얇은 shim 이다**(`src/win32_process_test_root.zig`). 그 파일을 직접 루트로
                // 걸면 모듈 경로가 `src/platform/windows/` 가 되어 `../../path_shape.zig` 가 밖이 된다.
                .root_source_file = b.path("src/win32_process_test_root.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        test_step.dependOn(&b.addRunArtifact(win32_process_tests).step);
    } else {
        test_step.dependOn(noteSkippedStep(b, "win32_process 단위 테스트", "Windows 호스트 전용 — CreateProcessW + 익명 파이프를 실제로 돌린다 (docs/windows-platform.md §2m.8)"));
    }

    // 크롬 텍스트 셰이핑의 **Windows 종단**. `system_text.zig` 의 macOS 테스트들은 CoreText 를 링크하는
    // 아티팩트 안에 있어서 Windows 에서는 하나도 안 돈다 — 이 스텝이 없으면 이음매 배선이 컴파일만 되고
    // **실행된 적이 없는** 상태로 남는다(실측으로 그랬다: 배선 직후 `zig build test` 에 system_text 테스트가
    // 한 줄도 안 나왔다). DirectWrite 를 실제로 부르므로 Windows 호스트에서만 건다.
    if (target.result.os.tag == .windows) {
        const chrome_system_text_win_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                // 루트는 얇은 shim 이다 — 그 파일을 직접 루트로 걸면 모듈 경로가
                // `src/platform/macos/chrome/` 이 되어 `../../../*.zig` 가 모듈 밖이 된다.
                .root_source_file = b.path("src/chrome_system_text_win_test_root.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        test_step.dependOn(&b.addRunArtifact(chrome_system_text_win_tests).step);
    } else {
        test_step.dependOn(noteSkippedStep(b, "크롬 셰이핑 Windows 종단", "Windows 호스트 전용 — DirectWrite 를 실제로 불러 글리프를 잰다 (docs/windows-platform.md §2m.18)"));
    }
    // exe(src/main.zig)는 control plane CLI가 unix domain socket과 POSIX 파일 모드(0600)를 직접 쓴다. 한때
    // 그래서 macOS에서만 걸었지만, W2가 그 자리들을 **호스트 OS 게이트**로 접어(컨트롤 소켓 → "인스턴스 없음",
    // `maru ssh`·`install-cli` → 미지원 안내, `publishBrowserResult` → `error.UnsupportedOnWindows`) 이제 모든
    // 호스트에서 컴파일된다. 그러니 모든 호스트에서 건다 — 그래야 "main.zig가 Windows에서 빌드된다"는 것이
    // **테스트로 지켜지는 성질**이 되지, 한 번 확인하고 마는 사실로 남지 않는다.
    // POSIX 전제가 진짜 필요한 테스트는 그 전제 자체로 skip한다(`@hasDecl(Permissions, "toMode")`).
    test_step.dependOn(&run_exe_tests.step);
    // ML2a/ML2b/ML3a Chrome tree는 layout·pointer state·semantic paint의 pure seam이다. 제품
    // host에 연결되기 전에도 기본 test에 넣어 Container/clip/capture/token-role contract가 CI 밖으로
    // 새지 않게 한다. `src/ui_test.zig`는 module root를 실제 `src/` 경계에 두면서, 전체 Chrome facade가
    // 아니라 새 typed UI namespace의 테스트만 모은다.
    const chrome_ui_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/ui_test.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_chrome_ui_tests = b.addRunArtifact(chrome_ui_tests);
    test_step.dependOn(&run_chrome_ui_tests.step);
    // 모바일 브리지는 OS 를 안 부르는 순수 Zig 라(docs/mobile-platform.md §3) 시뮬레이터 없이
    // 호스트에서 돈다. 여기 있는 계약은 전부 기기에서 앱을 죽이거나 화면을 지웠던 결함의
    // 재발 방지다 — 잡는 데 오래 걸린 것들이라 값이 싼 자리로 내려 둔다.
    const mobile_bridge_mod = b.addModule("mobile_bridge", .{
        .root_source_file = b.path("src/platform/mobile/mobile_bridge.zig"),
        .target = target,
        .optimize = optimize,
        .imports = &.{.{ .name = "maru", .module = maru_mod }},
    });
    const mobile_bridge_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/mobile_bridge_contract.zig"),
            .target = target,
            .optimize = optimize,
            // 화면 문구는 `maru.i18n` 이 단일 출처다 — 테스트가 문자열을 다시 적으면 원장이
            // 바뀌어도 초록이라, 같은 표를 읽어 대조한다.
            .imports = &.{
                .{ .name = "mobile_bridge", .module = mobile_bridge_mod },
                .{ .name = "maru", .module = maru_mod },
            },
        }),
    });
    // 키 id 표는 헤더가 단일 출처다. 한쪽만 고치면 host 가 모르는 id 를 보내고 키가 조용히
    // 사라지므로, 테스트가 **헤더를 그대로 읽어** 브리지 매핑과 대조한다.
    mobile_bridge_tests.root_module.addAnonymousImport("mobile_host_abi_for_test", .{
        .root_source_file = b.path("src/platform/mobile/mobile_host_abi.h"),
    });
    // 헤더를 C 로도 읽어 **인자 타입**까지 컴파일이 대조하게 한다(정규식 게이트의 사각지대).
    mobile_bridge_tests.root_module.addIncludePath(b.path("src/platform/mobile"));
    mobile_bridge_tests.root_module.link_libc = true;
    const run_mobile_bridge_tests = b.addRunArtifact(mobile_bridge_tests);
    test_step.dependOn(&run_mobile_bridge_tests.step);
    // 이 스위트만 따로 돌릴 수단이 필요하다. 전체 `test` 는 session host 테스트가 유닉스 소켓
    // 경로 상한에 걸려(`SocketPathTooLong`) **경로가 긴 워크트리에서는 원리상 통과할 수 없고**,
    // 모바일은 CI 가 없어 로컬 실행이 유일한 판정자다.
    const test_mobile_step = b.step("test-mobile", "Run the mobile bridge contract tests");
    test_mobile_step.dependOn(&run_mobile_bridge_tests.step);

    // SSH ABI 는 별도 파일이라 별도 모듈이다. **헤더는 같은 것을 읽는다** — 숫자의 단일 출처가
    // 하나여야 host 가 상태·결과 코드를 오해하지 않는다.
    const mobile_ssh_mod = b.addModule("mobile_ssh", .{
        .root_source_file = b.path("src/platform/mobile/mobile_ssh.zig"),
        .target = target,
        .optimize = optimize,
        .imports = &.{.{ .name = "maru", .module = maru_mod }},
    });
    const mobile_ssh_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/mobile_ssh_contract.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{.{ .name = "mobile_ssh", .module = mobile_ssh_mod }},
        }),
    });
    mobile_ssh_tests.root_module.addAnonymousImport("mobile_ssh_abi_for_test", .{
        .root_source_file = b.path("src/platform/mobile/mobile_host_abi.h"),
    });
    // **헤더를 C 로도 읽는다.** 이름·개수는 `abi_types.py` 가 정규식으로 보지만 인자 타입은
    // 못 본다 — `@cImport` 로 부르면 컴파일이 그것을 잡는다.
    mobile_ssh_tests.root_module.addIncludePath(b.path("src/platform/mobile"));
    mobile_ssh_tests.root_module.link_libc = true;
    const run_mobile_ssh_tests = b.addRunArtifact(mobile_ssh_tests);
    test_step.dependOn(&run_mobile_ssh_tests.step);
    test_mobile_step.dependOn(&run_mobile_ssh_tests.step);
    // **모바일 config 자신의 테스트도 돈다.** 이 파일은 브리지가 *import* 만 하므로 그 스위트에
    // 안 실린다 — 여기 있던 파싱·부분 저장 테스트가 **한 번도 안 돌고 있었다**(`mise run check`
    // 로그에 이름이 없는 것으로 확인했다). 스키마 밖 가지(서버 목록·프리셋)가 여기 있어
    // 브리지를 안 거치고 재는 자리가 필요하다.
    const mobile_config_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/platform/mobile/mobile_config.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{.{ .name = "maru", .module = maru_mod }},
        }),
    });
    const run_mobile_config_tests = b.addRunArtifact(mobile_config_tests);
    test_step.dependOn(&run_mobile_config_tests.step);
    test_mobile_step.dependOn(&run_mobile_config_tests.step);

    // 폰의 ndjson 클라이언트(S10d-1). **OS 가 없는 층이라 전부 잴 수 있다** — 줄 조립·프레임
    // 상한·`hello` 찾기·capabilities 판정이 여기 있고, 위 config 와 같은 이유로 브리지를 안 거치고
    // 잰다(브리지 계약 테스트는 ABI 를 지나야 해서 이 판정들을 직접 못 본다).
    const mobile_control_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/platform/mobile/mobile_control.zig"),
            .target = target,
            .optimize = optimize,
            // 프로토콜 이름을 **서버 것과 한 벌로** 든다(문자열을 옮겨 적지 않는다).
            .imports = &.{.{ .name = "maru", .module = maru_mod }},
        }),
    });
    const run_mobile_control_tests = b.addRunArtifact(mobile_control_tests);
    test_step.dependOn(&run_mobile_control_tests.step);
    test_mobile_step.dependOn(&run_mobile_control_tests.step);
    const test_mobile_control_step = b.step("test-mobile-control", "Run the phone-side ndjson control client tests only");
    test_mobile_control_step.dependOn(&run_mobile_control_tests.step);
    // 시각 골든 비교의 순수 코어. 스모크 캡처(PPM)를 관심 영역만 잘라 골든과 비교한다 — chrome/renderer의
    // 시각 결과를 지금까지 사람이 눈으로 확인해 왔고, 그 방식이 실제로 놓친 회귀가 있었다(부분적으로 보이는
    // 행이 "잘린" 것과 "세로로 눌린" 것을 구분하지 못했다). 코어는 순수 Zig라 어느 플랫폼에서도 돈다.
    const ppm_golden_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/support/ppm.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_ppm_golden_tests = b.addRunArtifact(ppm_golden_tests);
    test_step.dependOn(&run_ppm_golden_tests.step);
    const ppm_golden_step = b.step("test-ppm-golden", "Run the visual golden image comparison core tests");
    ppm_golden_step.dependOn(&run_ppm_golden_tests.step);

    // 실제 AppKit+Metal 캡처의 관심 영역을 커밋된 골든과 비교한다. 캡처가 없으면 skip하므로 스모크를
    // 돌리지 않은 환경/플랫폼에서도 무해하다(그 사실을 출력해 "게이트가 돌았다"는 착각을 막는다).
    const ppm_mod = b.addModule("ppm", .{
        .root_source_file = b.path("tests/support/ppm.zig"),
        .target = target,
    });
    const dock_visual_golden_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/golden/dock_visual.zig"),
            .target = target,
            .optimize = optimize,
            .link_libc = true,
            .imports = &.{.{ .name = "ppm", .module = ppm_mod }},
        }),
    });
    const run_dock_visual_golden = b.addRunArtifact(dock_visual_golden_tests);
    run_dock_visual_golden.setCwd(b.path("."));
    // 캡처는 스모크가 만들고 골든 갱신은 파일을 쓴다 — 캐시된 성공을 재사용하면 stale 판정이 된다.
    run_dock_visual_golden.has_side_effects = true;
    const dock_visual_golden_step = b.step("test-dock-visual-golden", "Compare Session Dock smoke captures against committed golden images");
    dock_visual_golden_step.dependOn(&run_dock_visual_golden.step);

    const chrome_ui_test_step = b.step("test-chrome-ui", "Run the focused typed Chrome UI tree, interaction, and paint tests");
    chrome_ui_test_step.dependOn(&run_chrome_ui_tests.step);

    // **편집기 판정자만 돌리는 스텝.** `zig build test`는 3,995개를 전부 돌려 20~30분이 걸리는데,
    // 그 대부분은 소켓·프로세스·타임아웃을 실제로 쓰는 `session_host` 계열이다. 편집기를 고치는
    // 동안 그것을 매번 기다리는 것은 낭비다 — 뮤턴트 하나 판정에 20분이 들어 적대적 검증이
    // 사실상 막혔다(2026-08-25).
    //
    // **`test`를 대신하지 않는다.** 필터가 걸려 있으므로 여기 통과는 편집기 판정자만의 통과이고,
    // 합류 전에는 `mise run check`가 전부 돈다. 이 스텝은 **고치는 동안의 되먹임**을 위한 것이다.
    const editor_test_module = b.createModule(.{
        .root_source_file = b.path("src/platform/macos/editor_judges.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .imports = &.{.{ .name = "maru", .module = maru_mod }},
    });
    if (target.result.os.tag == .macos) {
        editor_test_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{ "-fobjc-arc", "-fno-sanitize=undefined" },
        });
        editor_test_module.linkFramework("AppKit", .{});
        editor_test_module.linkFramework("Metal", .{});
        editor_test_module.linkFramework("MetalKit", .{});
        editor_test_module.linkFramework("QuartzCore", .{});
        editor_test_module.linkFramework("Foundation", .{});
        editor_test_module.linkFramework("CoreText", .{});
        editor_test_module.linkFramework("CoreGraphics", .{});
    }
    const editor_tests = addProjectTest(b, .{
        .root_module = editor_test_module,
        // **import와 필터를 함께 쓴다.** 진입 파일의 `test {}`가 대상 파일을 참조해 분석을
        // 강제하고(그것 없이 필터만 걸면 0개를 돌고도 통과한다 — 실측), 필터가 그 안에서 편집
        // 슬라이스의 판정자만 고른다. import만 두면 `editor.zig`가 `app_session.zig`를 들여와
        // 3,851개가 통째로 딸려온다(이것도 실측).
        // **`CRT`를 여기 적어 두었다가 0개를 돌았다**(적대적 검증 2026-08-26). caret 렌더 판정자와
        // 왕복 불변식 ①은 `src/chrome/components/editor_view/`에 있어 **이 바이너리에 없다** —
        // 필터에 이름을 적는 것과 그 판정자가 도는 것은 다르다. 그쪽은 아래 `test-chrome-ui`
        // 의존으로 실제로 돌린다.
        .filters = &.{ "MC", "EDIT", "UNDO", "SAVE", "EDOC", "FIND", "FOLD", "MOV", "CRT", "DIRTY", "COPY", "PASTE", "CUT", "CLIP", "SEL", "DEL", "CUR", "TAB", "ADV", "AID", "PAIR", "CMT", "LANG" },
    });
    const run_editor_tests = b.addRunArtifact(editor_tests);
    run_editor_tests.setCwd(b.path("."));
    const editor_test_step = b.step("test-editor", "Run the native editor judges only (fast feedback; not a substitute for `test`)");
    editor_test_step.dependOn(&run_editor_tests.step);
    // caret 렌더(`CRT*`)와 왕복 불변식 ①은 chrome 쪽 모듈에 있다 — 15초라 함께 돌린다.
    editor_test_step.dependOn(&run_chrome_ui_tests.step);
    // **L2 순수 모듈(`session/editor/*.zig`)의 판정자도 이 바이너리에 없다.** `app_session/editor.zig`가
    // 그것들을 **부르지만**, 부르는 것과 그 파일의 `test`가 함께 실려 오는 것은 다르다 — `maru`는 별도
    // 모듈이고 `zig test`는 루트 모듈의 test만 싣는다. `LANG`을 필터에 적어 놓고 **0개를 돌았다**
    // (적대적 검증 2026-08-27 — `CRT`와 똑같은 함정을 같은 파일에서 반복했다). 그래서 `maru` 모듈을
    // 뿌리로 하는 실행을 따로 걸어 편집기 L2 판정자를 **실제로** 돌린다.
    const editor_core_tests = addProjectTest(b, .{
        .root_module = maru_mod,
        .filters = &.{ "LANG", "MOT", "CLIP", "PAIR", "DLT", "BUF", "OCC", "FND" },
    });
    const run_editor_core_tests = b.addRunArtifact(editor_core_tests);
    run_editor_core_tests.setCwd(b.path("."));
    editor_test_step.dependOn(&run_editor_core_tests.step);
    // update_check.zig는 std만 의존하는 순수 로직(tag 파싱·semver 비교)이라 macOS smoke가 아니라
    // 기본 Zig test에서 어느 플랫폼에서든 돌린다(인앱 새 버전 안내의 판정 동작 고정).
    const update_check_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/platform/macos/update_check.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_update_check_tests = b.addRunArtifact(update_check_tests);
    test_step.dependOn(&run_update_check_tests.step);
    // validate_json_artifact.zig는 std만 의존하는 perf artifact 스키마 validator다. 부분 문자열
    // false-green 회귀(예산 10배가 통과하던 grep)와 스키마 락(누락·추가 키·타입)을 기본 test에서 고정한다.
    const perf_validate_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tools/perf/validate_json_artifact.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_perf_validate_tests = b.addRunArtifact(perf_validate_tests);
    test_step.dependOn(&run_perf_validate_tests.step);
    const session_host_connection_slot_mod = b.createModule(.{
        .root_source_file = b.path(
            "src/platform/macos/session_host/connection_slot.zig",
        ),
        .target = target,
        .optimize = optimize,
    });
    const session_host_slow_observer_validator_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path(
                "tools/perf/session_host_slow_observer_validator.zig",
            ),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "connection_slot", .module = session_host_connection_slot_mod },
            },
        }),
    });
    const run_session_host_slow_observer_validator_tests =
        b.addRunArtifact(session_host_slow_observer_validator_tests);
    test_step.dependOn(&run_session_host_slow_observer_validator_tests.step);
    // control_socket.zig(Track C 1b)는 실제 unix domain socket을 bind/accept하는 L4 컨트롤 플레인 부트스트랩이다.
    // getpeereid + std.c로 이식 가능하게 썼지만, 검증이 macOS에서만 되고 후속 slice(1e/1g)가 macOS 전용
    // xucred/LOCAL_PEERPID를 더하므로 **macOS에서만** test step에 배선한다(ubuntu CI에 미검증 Linux 소켓
    // 경로를 걸지 않는다 — un-gate는 Linux 호스트 검증 후 후속). maru 모듈(1a control_plane)을 import한다.
    if (target.result.os.tag == .macos) {
        const file_panel_termination_policy_tests = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-parse-as-library",
            "-target",
            swiftMacOSTarget(b, target.result),
        });
        file_panel_termination_policy_tests.addFileArg(b.path("src/platform/macos/FilePanelTerminationPolicy.swift"));
        file_panel_termination_policy_tests.addFileArg(b.path("tests/macos_file_panel_termination_policy.swift"));
        file_panel_termination_policy_tests.addArg("-o");
        const file_panel_termination_policy_test_bin = file_panel_termination_policy_tests.addOutputFileArg("maru-file-panel-termination-policy-tests");
        const run_file_panel_termination_policy_tests = b.addSystemCommand(&.{"/usr/bin/env"});
        run_file_panel_termination_policy_tests.addFileArg(file_panel_termination_policy_test_bin);
        test_step.dependOn(&run_file_panel_termination_policy_tests.step);

        // 종료 단계 계측은 실제 종료(앱 죽이기) 없이는 재현할 수 없어서, 시간 측정은 host가 하고 모으고
        // 표현하는 규칙만 순수 타입으로 떼어 여기서 증명한다(요약 필드 이름·순서·반올림 고정).
        const termination_timing_tests = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-parse-as-library",
            "-target",
            swiftMacOSTarget(b, target.result),
        });
        termination_timing_tests.addFileArg(b.path("src/platform/macos/TerminationTiming.swift"));
        termination_timing_tests.addFileArg(b.path("tests/macos_termination_timing.swift"));
        termination_timing_tests.addArg("-o");
        const termination_timing_test_bin = termination_timing_tests.addOutputFileArg("maru-termination-timing-tests");
        const run_termination_timing_tests = b.addSystemCommand(&.{"/usr/bin/env"});
        run_termination_timing_tests.addFileArg(termination_timing_test_bin);
        test_step.dependOn(&run_termination_timing_tests.step);

        // 종료 중 창을 미리 숨기면 isKeyWindow가 전부 false가 되어 workspace 활성 창 마커가 사라진다. 실제 숨김은
        // 앱을 죽여야 재현되므로 판정 규칙만 순수 타입으로 떼어 여기서 고정한다(같은 회귀의 재발 방지).
        const termination_window_policy_tests = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-parse-as-library",
            "-target",
            swiftMacOSTarget(b, target.result),
        });
        termination_window_policy_tests.addFileArg(b.path("src/platform/macos/TerminationWindowPolicy.swift"));
        termination_window_policy_tests.addFileArg(b.path("tests/macos_termination_window_policy.swift"));
        termination_window_policy_tests.addArg("-o");
        const termination_window_policy_test_bin = termination_window_policy_tests.addOutputFileArg("maru-termination-window-policy-tests");
        const run_termination_window_policy_tests = b.addSystemCommand(&.{"/usr/bin/env"});
        run_termination_window_policy_tests.addFileArg(termination_window_policy_test_bin);
        test_step.dependOn(&run_termination_window_policy_tests.step);

        const web_panel_hit_test_geometry_tests = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-parse-as-library",
            "-target",
            swiftMacOSTarget(b, target.result),
        });
        web_panel_hit_test_geometry_tests.addFileArg(b.path("src/platform/macos/WebPanelHitTestGeometry.swift"));
        web_panel_hit_test_geometry_tests.addFileArg(b.path("tests/macos_web_panel_hit_test_geometry.swift"));
        web_panel_hit_test_geometry_tests.addArgs(&.{ "-framework", "AppKit" });
        web_panel_hit_test_geometry_tests.addArg("-o");
        const web_panel_hit_test_geometry_test_bin = web_panel_hit_test_geometry_tests.addOutputFileArg("maru-web-panel-hit-test-geometry-tests");
        const run_web_panel_hit_test_geometry_tests = b.addSystemCommand(&.{"/usr/bin/env"});
        run_web_panel_hit_test_geometry_tests.addFileArg(web_panel_hit_test_geometry_test_bin);
        test_step.dependOn(&run_web_panel_hit_test_geometry_tests.step);

        const browser_result_registry_tests = b.addSystemCommand(&.{
            "xcrun",
            "swiftc",
            "-parse-as-library",
            "-target",
            swiftMacOSTarget(b, target.result),
        });
        browser_result_registry_tests.addFileArg(b.path("src/platform/macos/BrowserResultTransferRegistry.swift"));
        browser_result_registry_tests.addFileArg(b.path("tests/macos_browser_result_registry.swift"));
        browser_result_registry_tests.addArgs(&.{ "-framework", "JavaScriptCore" });
        browser_result_registry_tests.addArg("-o");
        const browser_result_registry_test_bin = browser_result_registry_tests.addOutputFileArg("maru-browser-result-registry-tests");
        const run_browser_result_registry_tests = b.addSystemCommand(&.{"/usr/bin/env"});
        run_browser_result_registry_tests.addFileArg(browser_result_registry_test_bin);
        test_step.dependOn(&run_browser_result_registry_tests.step);

        const control_socket_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/control_socket.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        const run_control_socket_tests = b.addRunArtifact(control_socket_tests);
        test_step.dependOn(&run_control_socket_tests.step);
        // control_server.zig(Track C A2b)는 앱 전역 라이브 컨트롤 소켓 + accept 스레드 + 메인 marshal 큐다.
        // control_socket과 같은 이유로 **macOS에서만** test step에 배선한다(실 unix socket·스레드·peer-cred).
        const control_server_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/control_server.zig"),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        const run_control_server_tests = b.addRunArtifact(control_server_tests);
        test_step.dependOn(&run_control_server_tests.step);
    }
    // coretext_font.zig는 Objective-C/CoreText runtime을 직접 호출하지 않는 제품 후보
    // adapter다. 그래서 macOS smoke opt-in에 숨기지 말고 기본 Zig test에서 돌린다.
    test_step.dependOn(&run_macos_coretext_font_tests.step);
    // coretext_probe.zig는 native smoke ABI record를 제품 후보 CoreText record로 바꾸는
    // probe 전용 경계다. Objective-C 없이 돌려서 smoke 파일이 변환 규칙을 다시 소유하지
    // 않는지 기본 테스트에서 고정한다.
    test_step.dependOn(&run_macos_coretext_probe_tests.step);
    // coretext_shaper.zig도 native CoreText runtime을 직접 호출하지 않고, 이미 shape된
    // CoreText glyph record를 renderer GlyphRunList로 넘기는 제품 후보 경계만 검증한다.
    test_step.dependOn(&run_macos_coretext_shaper_tests.step);
    // coretext_raster.zig는 Objective-C bridge를 함수 포인터로 주입받는 제품 후보
    // rasterizer 경계다. 기본 테스트에서는 native CoreText 없이 FontId -> PostScript name
    // 조회와 renderer RasterizerFailed 매핑 계약만 고정한다.
    test_step.dependOn(&run_macos_coretext_raster_tests.step);
    // coretext_frame_builder.zig는 active surface를 CoreText shaper/rasterizer가 들어간
    // AppHostFrame으로 조립하는 제품 후보 경계다. native bridge는 함수 포인터로 주입하므로
    // 기본 테스트에서는 Objective-C 없이 FrameLoop가 호출할 builder 계약을 고정한다.
    test_step.dependOn(&run_macos_coretext_frame_builder_tests.step);
    // app_host_abi.zig는 제품 Swift host가 호출할 C ABI의 version/layout/ownership 신호를 고정한다.
    // ABI layout 자체는 플랫폼 독립이지만 이 모듈은 `app_session`을 끌어와 POSIX fd·AT.FDCWD까지 함께
    // 컴파일된다(실측: Windows에서 209개 에러) — 즉 실제로는 macOS 전용 artifact다. 위 coretext_* 는
    // 진짜 플랫폼 독립이라(Windows에서 통과 확인) 게이트하지 않고 그대로 기본 test에 남긴다.
    if (macos_host_tests) test_step.dependOn(&run_macos_app_host_abi_tests.step);

    const e2e_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/e2e/headless.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "test_support", .module = test_support_mod },
            },
        }),
    });
    const run_e2e_tests = b.addRunArtifact(e2e_tests);
    run_e2e_tests.setCwd(b.path("."));

    const e2e_step = b.step("test-e2e", "Run headless E2E tests");
    e2e_step.dependOn(&run_e2e_tests.step);

    const pty_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/integration/pty/macos.zig"),
            .target = target,
            .optimize = optimize,
            .link_libc = true,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "test_support", .module = test_support_mod },
            },
        }),
    });
    const run_pty_tests = b.addRunArtifact(pty_tests);
    run_pty_tests.setCwd(b.path("."));

    const pty_step = b.step("test-pty", "Run opt-in macOS PTY integration tests, including interactive shell smoke");
    pty_step.dependOn(&run_pty_tests.step);

    const oracle_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/oracle/recorded.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "test_support", .module = test_support_mod },
            },
        }),
    });
    const run_oracle_tests = b.addRunArtifact(oracle_tests);
    run_oracle_tests.setCwd(b.path("."));

    const oracle_step = b.step("test-oracle", "Compare Maru snapshots against recorded terminal oracles");
    oracle_step.dependOn(&run_oracle_tests.step);

    // Trace fixture + CI: replay committed trace fixtures and assert the reconstructed screen matches the golden
    // (and that each fixture passes the redaction guard, so it is commit-safe). Runs in the default `test` step.
    const replay_fixture_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/oracle/replay.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "test_support", .module = test_support_mod },
            },
        }),
    });
    const run_replay_fixture_tests = b.addRunArtifact(replay_fixture_tests);
    run_replay_fixture_tests.setCwd(b.path("."));
    test_step.dependOn(&run_replay_fixture_tests.step);

    const replay_step = b.step("test-replay", "Replay committed trace fixtures against golden screens (MARU_UPDATE_GOLDEN=1 to refresh)");
    replay_step.dependOn(&run_replay_fixture_tests.step);

    const boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/imports.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_boundary_tests = b.addRunArtifact(boundary_tests);
    run_boundary_tests.setCwd(b.path("."));

    // chrome 셀 텍스트의 grapheme cluster 규율(CG1) — 셀을 만드는 함수가 문자열을 codepoint 단위로 디코드하면
    // NFD가 자모로 흩어진다(docs/grapheme-clustering.md §3.1a). import 경계와 같은 결의 소스 스캔이라 같은 step에 건다.
    const chrome_text_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/chrome_text_clusters.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_chrome_text_boundary_tests = b.addRunArtifact(chrome_text_boundary_tests);
    run_chrome_text_boundary_tests.setCwd(b.path("."));

    // 아이콘 이름 규율(IC2) — 등록 아이콘을 codepoint 리터럴(`0xF0023`·`"\u{F0023}"`)로 부르면 어느 그림인지
    // 안 읽히고 자산 재배치 때 조용히 폰트 폴백으로 빠진다(docs/chrome-strategy.md §9.7). 같은 결의 소스 스캔.
    const icon_literal_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/icon_literals.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_icon_literal_boundary_tests = b.addRunArtifact(icon_literal_boundary_tests);
    run_icon_literal_boundary_tests.setCwd(b.path("."));

    // cwd 축 규율 — "이 터미널이 서 있는 폴더"를 푸는 지점이 하나여야 한다(docs/editor-surface-dock.md §3.5).
    // 그 규칙이 주석에만 있던 동안 소비자 여섯이 관측(`observation.cwd`)을 직독해 갈렸고, 셸 통합이 없는 셸과
    // 재개 Term에서 사이드바·상태바·검색·도크 범위 칩·대화 매핑이 한꺼번에 죽었다. 같은 결의 소스 스캔으로
    // 정당한 직독의 **개수를 고정**한다(0건 규칙은 세울 수 없다 — Q1 직독이 실재한다).
    const cwd_axis_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/cwd_axis.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_cwd_axis_boundary_tests = b.addRunArtifact(cwd_axis_boundary_tests);
    run_cwd_axis_boundary_tests.setCwd(b.path("."));

    // `fstat` 축(`file_tree.ScanIdentity`)을 만들거나 벗기는 자리를 재고로 고정한다. Zig 는 필드
    // 프라이버시가 없어 타입만으로는 `.{ .value = 아무거나 }` 를 막지 못한다 — 언어가 못 하는 봉인을
    // 이 소스 스캔이 대신한다(2026-08-21: 축을 섞어 탐색기 안내가 끊이지 않던 결함).
    const scan_identity_axis_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/scan_identity_axis.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_scan_identity_axis_boundary_tests = b.addRunArtifact(scan_identity_axis_boundary_tests);
    run_scan_identity_axis_boundary_tests.setCwd(b.path("."));

    // 중립 층으로 가는 경로를 native 구분자로 잇지 않는다 — Windows 전용 오답이라 macOS·Linux 러너에는
    // 안 보인다. 소스 스캔이 그 배선을 CI 로 끌어오는 유일한 길이다(docs/windows-platform.md §2m.5).
    const neutral_path_join_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/neutral_path_join.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_neutral_path_join_boundary_tests = b.addRunArtifact(neutral_path_join_boundary_tests);
    run_neutral_path_join_boundary_tests.setCwd(b.path("."));

    // cli/ 순수 경계 — `cli/`의 제품 코드는 파싱·wire·렌더만 갖고 소켓/프로세스/파일 syscall은 명시된
    // 예외 파일에만 둔다. 그 순수성이 파서·validator를 살아 있는 앱 없이 단위 테스트할 수 있는 근거인데,
    // 2026-08-16까지 그 규칙은 **파일 주석에만** 있었다(imports.zig의 강제 레이어 목록에 src/cli가 없었다).
    // facade-contracts.md "import boundary는 테스트로 확인한다"에 맞춰 같은 결의 소스 스캔으로 닫는다.
    const cli_purity_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/cli_purity.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_cli_purity_boundary_tests = b.addRunArtifact(cli_purity_boundary_tests);
    run_cli_purity_boundary_tests.setCwd(b.path("."));

    // IME 조합 확정 규칙의 **모달리티 목록** — AppKit 입력기 세션 종료는 NSView만 할 수 있어서 이 규칙은
    // chokepoint 하나로 닫히지 않고 Swift 입력 경계마다 합류시켜야 하는 열린 목록이다. 빠뜨리면 그 경로에서만
    // 조합 잔상이 남는다(실측 두 번: 탭 전환·드롭). Swift 는 단위 테스트 하니스가 없어 소스 스캔으로 든다.
    const ime_commit_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/ime_commit_modalities.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_ime_commit_boundary_tests = b.addRunArtifact(ime_commit_boundary_tests);
    run_ime_commit_boundary_tests.setCwd(b.path("."));

    // i18n: 세션 생성 경로마다 로케일을 넘기는가. 안 넘기면 `ui.language = auto`가 조용히 영어로
    // 떨어진다 — 크래시도 경고도 없이 화면 언어만 틀리므로 컴파일러도 테스트도 못 잡는다. 실제로 I4a에서
    // 두 번째 생성 경로(quick 패널)를 빠뜨렸다. 단일 출처: docs/i18n.md §5.1.
    const i18n_locale_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/i18n_locale_injection.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_i18n_locale_boundary_tests = b.addRunArtifact(i18n_locale_boundary_tests);
    run_i18n_locale_boundary_tests.setCwd(b.path("."));

    // sans-io: SSH 프로토콜 층이 소켓·파일·시계를 만지는가. 모바일 브리지는 계약상 OS 호출이 0 이라
    // (docs/ssh-client.md §2) 그 성질이 깨지면 **모바일 링크 오류로 늦게** 드러난다. 허용 목록 방식이고
    // 디렉터리를 직접 훑는다 — 앞선 판정자가 금지 목록 + 등록 개수라서 무력했던 실측을 그 파일이 적어 뒀다.
    const ssh_sans_io_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/ssh_sans_io.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_ssh_sans_io_boundary_tests = b.addRunArtifact(ssh_sans_io_boundary_tests);
    run_ssh_sans_io_boundary_tests.setCwd(b.path("."));

    // **이 집계 step 은 boundary 테스트를 Debug 로만 돈다.** 아래 optimize 루프 안에서 등록되는 것들은
    // `if (<loop>_optimize == .Debug)` 로 걸러 붙는다. 이유는 boundary 테스트가 하는 일 자체다 —
    // 46개 중 44개가 `readSource` 로 소스 파일을 문자열로 읽어 선언 수·제품 caller 수를 세고, `maru`
    // 모듈을 import 하는 것은 0개다. 세는 결과는 최적화 모드에 따라 달라질 수 없으므로 ReleaseFast
    // 사본은 같은 답을 내려고 바이너리를 한 번 더 링크하는 비용일 뿐이다.
    //
    // 실측(2026-08-17, ubuntu-latest 2코어): `mise run check` 안에서 mise 가 태스크를 병렬로 돌리는데
    // `check-boundaries` 만 13분 35초였고 나머지는 전부 1~39초였다 — 즉 `check` job 14분이 사실상
    // 이 step 하나였다. 등록이 68개이고 그 중 33개가 두 모드로 링크되던 구조가 원인이다.
    //
    // 개별 집중 gate(`test-session-host-*`)는 **바꾸지 않는다.** 그쪽은 "Debug·ReleaseFast runtime
    // N+boundary 1 exact-count" 계약을 문서가 소유하므로 두 모드를 그대로 돌린다. 그 gate 를 직접
    // 부를 때만 ReleaseFast boundary 가 빌드되고, CI 의 집계 경로에서는 빠진다.
    // i18n 2차 방어: 번역 대상 레이어에 새 한국어 리터럴이 들어오지 않는가. 1차(파라미터 타입)를
    // 세울 수 없는 sink가 남으므로(정적·동적이 섞이는 컬렉션 — 계약 §7.2) 거기서는 이 검사가 유일한
    // 방어다. 개수 원장이라 늘어도 줄어도 실패한다(줄면 원장을 함께 줄이라는 뜻).
    const i18n_literal_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/i18n_literals.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_i18n_literal_boundary_tests = b.addRunArtifact(i18n_literal_boundary_tests);
    run_i18n_literal_boundary_tests.setCwd(b.path("."));

    // 머지 충돌 마커가 커밋되지 않는가. 코드였다면 `zig build` 가 즉시 잡지만(문법 오류), 문서·스크립트는
    // 깨져도 조용하다 — 실제로 `docs/file-explorer.md` 에 하나가 커밋된 채 남아 있었다.
    const conflict_marker_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/conflict_markers.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_conflict_marker_boundary_tests = b.addRunArtifact(conflict_marker_boundary_tests);
    run_conflict_marker_boundary_tests.setCwd(b.path("."));

    // i18n 3차 방어: 표에 **아무도 안 쓰는 키**가 남지 않는가. 1차(파라미터 타입)·2차(리터럴 개수)는
    // "화면 문자열이 키를 거치는가"를 보지만, 되돌린 작업의 잔해로 남은 키는 둘 다 통과한다 — 실제로
    // 15개가 쌓여 있었다. 참조 0이면 실패하고 이름을 전부 출력한다.
    const i18n_orphan_key_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/i18n_orphan_keys.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_i18n_orphan_key_boundary_tests = b.addRunArtifact(i18n_orphan_key_boundary_tests);
    run_i18n_orphan_key_boundary_tests.setCwd(b.path("."));

    // i18n 4차 방어: 표시 문자열이 **한 언어로 얼어붙지** 않는가. 컴파일러는 절반만 막는다 —
    // 컨테이너 수준 `const` 에 `i18n.t()` 를 넣으면 거부하지만(comptime-known 아님), 언어를 인자로 박은
    // `i18n.tIn(.ko, …)` 는 통과하고 그 자리에서 굳는다. 한글 리터럴이 없으니 리터럴 게이트도 못 본다.
    const i18n_pinned_language_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/boundary/pinned_language.zig"),
            .target = target,
            .optimize = optimize,
            // 표의 **가시성 하나**를 컴파일러에게 묻는다(`@hasDecl` 세 줄) — `en`/`ko`/`Table` 이 다시
            // `pub` 이 되면 comptime 에 거부한다. 그 셋을 비공개로 닫은 것이 이 브랜치의 변경이고,
            // 문자열로 되묻지 않으려면 표를 모듈로 받아야 한다. 대가는 이 테스트가 단독 `zig test` 로
            // 안 돈다는 것이고, 붙이는 명령은 그 파일 머리에 적혀 있다.
            //
            // 표의 **공개 표면 전체**를 명부로 고정하는 판도 있었으나 걷어냈다(위반 0 인 가정 방어였다).
            // 그래서 다른 이름으로 재수출하는 것(`pub const ko2 = ko;`)은 **이 게이트가 안 잡는다** —
            // 인정된 한계로 `pinned_language.zig` 머리와 `docs/i18n.md` §7.2 에 적혀 있다.
            .imports = &.{.{ .name = "i18n_table", .module = b.createModule(.{
                .root_source_file = b.path("src/i18n.zig"),
                .target = target,
                .optimize = optimize,
            }) }},
        }),
    });
    const run_i18n_pinned_language_boundary_tests = b.addRunArtifact(i18n_pinned_language_boundary_tests);
    run_i18n_pinned_language_boundary_tests.setCwd(b.path("."));

    const boundary_step = b.step("check-boundaries", "Check facade import boundaries");
    const session_host_cr6d_global_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/session_host_cr6d_boundary.zig"),
            .target = target,
            .optimize = optimize,
        }),
        .filters = &.{"CR6d 경계는"},
    });
    const run_session_host_cr6d_global_boundary_tests = b.addRunArtifact(session_host_cr6d_global_boundary_tests);
    run_session_host_cr6d_global_boundary_tests.addArg("--maru-expect-tests=1");
    run_session_host_cr6d_global_boundary_tests.setCwd(b.path("."));
    boundary_step.dependOn(&run_session_host_cr6d_global_boundary_tests.step);
    const session_host_cr6e_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/session_host_cr6e_boundary.zig"),
            .target = target,
            .optimize = optimize,
        }),
        .filters = &.{ "CR6e-a1 경계는", "CR6e-a2 경계는" },
    });
    const run_session_host_cr6e_boundary_tests = b.addRunArtifact(session_host_cr6e_boundary_tests);
    run_session_host_cr6e_boundary_tests.addArg("--maru-expect-tests=2");
    run_session_host_cr6e_boundary_tests.setCwd(b.path("."));
    boundary_step.dependOn(&run_session_host_cr6e_boundary_tests.step);
    const session_host_cr6f_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/session_host_cr6f_boundary.zig"),
            .target = target,
            .optimize = optimize,
        }),
        .filters = &.{"CR6f output wake"},
    });
    const run_session_host_cr6f_boundary_tests = b.addRunArtifact(session_host_cr6f_boundary_tests);
    run_session_host_cr6f_boundary_tests.addArg("--maru-expect-tests=1");
    run_session_host_cr6f_boundary_tests.setCwd(b.path("."));
    const session_host_cr6f_step = b.step(
        "test-session-host-cr6f",
        "Verify CR6f output wake ownership and source boundaries",
    );
    session_host_cr6f_step.dependOn(&run_session_host_cr6f_boundary_tests.step);
    boundary_step.dependOn(&run_session_host_cr6f_boundary_tests.step);
    const session_host_e2a_step = b.step(
        "test-session-host-e2a",
        "Verify P4 E2a runtime observation cache transaction in Debug and ReleaseFast",
    );
    for ([_]std.builtin.OptimizeMode{ .Debug, .ReleaseFast }) |e2a_optimize| {
        const session_host_e2a_cache_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/session_host/runtime_observation_cache.zig"),
                .target = target,
                .optimize = e2a_optimize,
            }),
            .filters = &.{"P4 E2a"},
        });
        const run_session_host_e2a_cache_tests = b.addRunArtifact(session_host_e2a_cache_tests);
        run_session_host_e2a_cache_tests.addArg("--maru-expect-tests=7");
        session_host_e2a_step.dependOn(&run_session_host_e2a_cache_tests.step);
    }
    const session_host_e2a_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/session_host_e2a_boundary.zig"),
            .target = target,
            .optimize = optimize,
        }),
        .filters = &.{"P4 E2a cache"},
    });
    const run_session_host_e2a_boundary_tests = b.addRunArtifact(session_host_e2a_boundary_tests);
    run_session_host_e2a_boundary_tests.addArg("--maru-expect-tests=1");
    run_session_host_e2a_boundary_tests.setCwd(b.path("."));
    session_host_e2a_step.dependOn(&run_session_host_e2a_boundary_tests.step);
    boundary_step.dependOn(&run_session_host_e2a_boundary_tests.step);
    const session_host_e2b_step = b.step(
        "test-session-host-e2b",
        "Verify P4 E2b runtime-shared observation cache product wiring",
    );
    for ([_]std.builtin.OptimizeMode{ .Debug, .ReleaseFast }) |e2b_optimize| {
        const session_host_e2b_manager_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/session_host/runtime_manager.zig"),
                .target = target,
                .optimize = e2b_optimize,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
            .filters = &.{"P4 E2b"},
        });
        const run_session_host_e2b_manager_tests = b.addRunArtifact(session_host_e2b_manager_tests);
        run_session_host_e2b_manager_tests.addArg("--maru-expect-tests=1");
        session_host_e2b_step.dependOn(&run_session_host_e2b_manager_tests.step);
    }
    const session_host_e2b_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/session_host_e2b_boundary.zig"),
            .target = target,
            .optimize = optimize,
        }),
        .filters = &.{"P4 E2b product"},
    });
    const run_session_host_e2b_boundary_tests = b.addRunArtifact(session_host_e2b_boundary_tests);
    run_session_host_e2b_boundary_tests.addArg("--maru-expect-tests=1");
    run_session_host_e2b_boundary_tests.setCwd(b.path("."));
    session_host_e2b_step.dependOn(&run_session_host_e2b_boundary_tests.step);
    boundary_step.dependOn(&run_session_host_e2b_boundary_tests.step);
    const session_host_e2c_step = b.step(
        "test-session-host-e2c",
        "Verify P4 E2c observation source-change scaling at 1, 10, and 100 runtimes",
    );
    const session_host_e2c_manager_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/platform/macos/session_host/runtime_manager.zig"),
            .target = target,
            .optimize = .ReleaseFast,
            .imports = &.{.{ .name = "maru", .module = maru_mod }},
        }),
        .filters = &.{"P4 E2c"},
    });
    const run_session_host_e2c_manager_tests = b.addRunArtifact(session_host_e2c_manager_tests);
    run_session_host_e2c_manager_tests.addArg("--maru-expect-tests=1");
    session_host_e2c_step.dependOn(&run_session_host_e2c_manager_tests.step);
    const session_host_e2c_boundary_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/session_host_e2c_boundary.zig"),
            .target = target,
            .optimize = optimize,
        }),
        .filters = &.{"P4 E2c source change"},
    });
    const run_session_host_e2c_boundary_tests = b.addRunArtifact(session_host_e2c_boundary_tests);
    run_session_host_e2c_boundary_tests.addArg("--maru-expect-tests=1");
    run_session_host_e2c_boundary_tests.setCwd(b.path("."));
    session_host_e2c_step.dependOn(&run_session_host_e2c_boundary_tests.step);
    boundary_step.dependOn(&run_session_host_e2c_boundary_tests.step);
    const session_host_input_parity_step = b.step(
        "test-session-host-input-parity",
        "Verify P4 host-backed DECSET 1003 motion and authoritative selection autoscroll",
    );
    session_host_input_parity_step.dependOn(session_host_e2c_step);
    for ([_]std.builtin.OptimizeMode{ .Debug, .ReleaseFast }) |input_parity_optimize| {
        const input_parity_app_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/app_session.zig"),
                .target = target,
                .optimize = input_parity_optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
            .filters = &.{"host-backed motion 리포팅"},
        });
        input_parity_app_tests.root_module.linkFramework("AppKit", .{});
        input_parity_app_tests.root_module.linkFramework("Metal", .{});
        input_parity_app_tests.root_module.linkFramework("MetalKit", .{});
        input_parity_app_tests.root_module.linkFramework("QuartzCore", .{});
        input_parity_app_tests.root_module.linkFramework("CoreText", .{});
        input_parity_app_tests.root_module.linkFramework("CoreGraphics", .{});
        input_parity_app_tests.root_module.addCSourceFile(.{
            .file = b.path("src/platform/macos/coretext_smoke.m"),
            .flags = &.{ "-fobjc-arc", "-fno-sanitize=undefined" },
        });
        const run_input_parity_app_tests = b.addRunArtifact(input_parity_app_tests);
        // app_session root의 세 무명 sentinel과 1003 관측 게이트 한 행.
        run_input_parity_app_tests.addArg("--maru-expect-tests=4");
        run_input_parity_app_tests.setCwd(b.path("."));
        session_host_input_parity_step.dependOn(&run_input_parity_app_tests.step);

        const input_parity_host_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/platform/macos/session_host/runtime_manager.zig"),
                .target = target,
                .optimize = input_parity_optimize,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
            .filters = &.{
                "P4 input parity: host reader writes DECSET 1003 motion to the real PTY",
                "runtime manager: host selection scroll-and-extend is fenced before authoritative copy",
            },
        });
        const run_input_parity_host_tests = b.addRunArtifact(input_parity_host_tests);
        run_input_parity_host_tests.addArg("--maru-expect-tests=2");
        run_input_parity_host_tests.setCwd(b.path("."));
        session_host_input_parity_step.dependOn(&run_input_parity_host_tests.step);

        const input_parity_boundary_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("tests/session_host_input_parity_boundary.zig"),
                .target = target,
                .optimize = input_parity_optimize,
            }),
