    boundary_step.dependOn(&run_chrome_text_boundary_tests.step);
    boundary_step.dependOn(&run_icon_literal_boundary_tests.step);
    boundary_step.dependOn(&run_cwd_axis_boundary_tests.step);
    boundary_step.dependOn(&run_scan_identity_axis_boundary_tests.step);
    boundary_step.dependOn(&run_neutral_path_join_boundary_tests.step);
    boundary_step.dependOn(&run_cli_purity_boundary_tests.step);
    boundary_step.dependOn(&run_i18n_locale_boundary_tests.step);
    boundary_step.dependOn(&run_i18n_literal_boundary_tests.step);
    boundary_step.dependOn(&run_i18n_orphan_key_boundary_tests.step);
    boundary_step.dependOn(&run_ssh_sans_io_boundary_tests.step);

    // SSH 층은 **세 최적화 모드로 다 돈다.** `std` 의 몇몇 검사가 `if (std.debug.runtime_safety)`
    // 뒤에 있어 **배포가 쓰는 ReleaseFast 에서 사라지는데**, `zig build test` 는 Debug 라 CI 가
    // 영영 못 본다 — 실제로 개인키 공개키 대조가 그렇게 빠져 있었다(docs/ssh-client.md §4.4.4).
    const ssh_mode_step = b.step("check-ssh-modes", "Run the SSH core in Debug/ReleaseSafe/ReleaseFast");
    for ([_]std.builtin.OptimizeMode{ .Debug, .ReleaseSafe, .ReleaseFast }) |mode| {
        const ssh_modes = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path("src/session/ssh/ssh.zig"),
                .target = target,
                .optimize = mode,
            }),
        });
        const run_ssh_modes = b.addRunArtifact(ssh_modes);
        run_ssh_modes.setCwd(b.path("."));
        ssh_mode_step.dependOn(&run_ssh_modes.step);
    }
    boundary_step.dependOn(ssh_mode_step);

    // **내장 SSH 클라이언트의 실서버 스모크**(계획 S8). 제품 경로가 아니라 시험대다 — 데스크톱의
    // `maru ssh` 는 시스템 `ssh` 래퍼로 그대로 두고(계약 §3.4), 내장 클라이언트는 모바일용이다.
    // `src/session/ssh/` 는 전부 sans-io 라 스스로는 아무 데도 못 붙으므로, 소켓을 든 이 드라이버가
    // 있어야 진짜 sshd 와 왕복할 수 있다. sshd 를 띄우고 키를 만드는 일은 `tools/ssh/client_smoke.sh`
    // 가 한다(없으면 SKIP — 환경 의존이라 기본 `check` 에 안 넣는다).
    // **드라이버 셋 전부가 POSIX 호스트 전용이다** — Windows 에서는 스텝이 아무것도 안 만든다.
    // 이유가 두 겹이고 **둘 다 실측했다**:
    //
    // ⒜ **Zig 쪽이 raw BSD 소켓을 든다.** `tools/ssh/{client,abi}_smoke.zig` 가 `std.c.socket`·
    //    `std.c.open` 을 직접 부르는데 Windows 에서 `std.c.O` 는 `void` 라 컴파일이 안 된다
    //    (`parameter of type 'void' not allowed in calling convention 'x86_64_win'`).
    //    `std.process.Args.Iterator.init` 도 Windows 에서는 `@compileError` 다.
    //    Zig 0.16 의 크로스플랫폼 소켓 API 는 `std.Io.net` 인데 **이 저장소는 아직 한 곳도 안 쓴다.**
    // ⒝ **더 중요한 것 — 구동할 하네스가 없다.** `tools/ssh/client_smoke.sh` 는 `#!/bin/sh` 이고
    //    `/usr/sbin/sshd`·`ssh-keygen` 을 찾아 일회용 sshd 를 띄운다. 즉 Zig 쪽만 포팅해도
    //    **Windows 에서 그 바이너리를 돌릴 것이 없다** — 검증되지 않은 소켓 코드만 한 벌 남는다.
    //
    // 그래서 지금은 가른다. Windows 에서 이 스모크를 진짜로 돌리려면 ⒜ `std.Io.net` 포팅과
    // ⒝ OpenSSH for Windows 를 쓰는 PowerShell 하네스가 **둘 다** 필요하고, 그것은 `maru ssh` 의
    // Windows 지원(W9, docs/plans/windows-platform.md)과 함께 갈 일이다.
    //
    // **어떤 게이트도 이 스텝에 의존하지 않는다**(CI·mise 도 안 부른다). 그래서 여기서 빠지는 것이
    // 다른 검사를 조용히 비우지 않는다 — `zig build test` 는 이것과 무관하게 돈다.
    const ssh_smoke_host_supported = target.result.os.tag != .windows;
    const ssh_client_smoke_step = b.step("ssh-client-smoke", "Build the built-in SSH client real-server smoke driver (POSIX hosts only)");
    if (ssh_smoke_host_supported) {
        const ssh_client_smoke_exe = b.addExecutable(.{
            .name = "ssh-client-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("tools/ssh/client_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        ssh_client_smoke_step.dependOn(&b.addInstallArtifact(ssh_client_smoke_exe, .{}).step);

        // **모바일 ABI 로만** 같은 sshd 에 붙는 드라이버(S9-2). 위 스모크는 코어가 실서버에서 돈다는
        // 것을 증명하지만 그 사이의 ABI 는 한 줄도 안 지난다 — 기기에서 "안 된다" 가 났을 때
        // 프로토콜 탓인지 배선 탓인지 가르려면 이 층만으로 한 번 붙여 봐야 한다.
        const ssh_abi_smoke_exe = b.addExecutable(.{
            .name = "ssh-abi-smoke",
            .root_module = b.createModule(.{
                .root_source_file = b.path("tools/ssh/abi_smoke.zig"),
                .target = target,
                .optimize = optimize,
                .imports = &.{
                    .{ .name = "maru", .module = maru_mod },
                    .{ .name = "mobile_ssh", .module = mobile_ssh_mod },
                },
            }),
        });
        ssh_client_smoke_step.dependOn(&b.addInstallArtifact(ssh_abi_smoke_exe, .{}).step);
    } else {
        ssh_client_smoke_step.dependOn(noteSkippedStep(b, "ssh-client-smoke", "POSIX 호스트 전용 — raw BSD 소켓 + `#!/bin/sh` sshd 하네스 (docs/mobile-platform.md §2)"));
    }

    // **두 host 가 쓸 C 펌프**(`src/platform/mobile_host/ssh_pump.c`)를 그대로 링크해 실서버와
    // 왕복한다. 기기에 올리기 전에 소켓·스레드·세션 루프·호스트키 핀이 도는 것을 여기서 본다 —
    // 그러면 기기에서 실패했을 때 남는 후보가 host 배선뿐이다.
    //
    // **호스트 타깃이 Windows 면 통째로 뺀다.** 펌프는 iOS·Android host 가 쓰는 **POSIX 코드**다 —
    // `<netdb.h>`·`<sys/socket.h>` 를 직접 부르고, 스모크(`tools/ssh/pump_smoke.zig`)도 `std.c.timespec`
    // 처럼 Windows 에서 `void` 로 풀리는 타입을 쓴다. Windows 타깃은 이 펌프의 **소비자가 아니다**
    // (모바일 = iOS + Android). 그런데 스텝이 무조건 걸려 있어 Windows 기기에서는 `zig build test` 가
    // 통째로 실패했다 — 자기 변경과 무관한 빨강이라 그 기기의 개발자가 게이트를 아예 못 돌린다.
    //
    // **이식성 가드는 그대로 남는다.** 아래 `check-ssh-pump-portable` 이 linux-gnu 로 **크로스 컴파일**
    // 하므로 어느 호스트에서도 돌고, 그것이 이 파일의 진짜 이식성 검사다(glibc feature macro 사고를
    // 잡으려고 만든 자리). 여기서 빠지는 것은 **호스트에서 실서버와 왕복하는 스모크**뿐이다.
    const pump_host_supported = target.result.os.tag != .windows;
    if (pump_host_supported) {
        const ssh_pump_mod = b.createModule(.{
            .root_source_file = b.path("tools/ssh/pump_smoke.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{.{ .name = "mobile_ssh", .module = mobile_ssh_mod }},
        });
        ssh_pump_mod.addIncludePath(b.path("src/platform/mobile_host"));
        ssh_pump_mod.addIncludePath(b.path("src/platform/mobile"));
        ssh_pump_mod.addCSourceFile(.{ .file = b.path("src/platform/mobile_host/ssh_pump.c"), .flags = &.{"-std=c11"} });
        ssh_pump_mod.link_libc = true;
        const ssh_pump_smoke_exe = b.addExecutable(.{ .name = "ssh-pump-smoke", .root_module = ssh_pump_mod });
        ssh_client_smoke_step.dependOn(&b.addInstallArtifact(ssh_pump_smoke_exe, .{}).step);

        // 펌프의 단위 테스트(핀 없는 접속·인자 검사)는 소켓을 쓰므로 sans-io 게이트 밖이다.
        const ssh_pump_tests = addProjectTest(b, .{ .root_module = ssh_pump_mod });
        const run_ssh_pump_tests = b.addRunArtifact(ssh_pump_tests);
        test_step.dependOn(&run_ssh_pump_tests.step);
        test_mobile_step.dependOn(&run_ssh_pump_tests.step);
    } else {
        // 같은 이유로 `test`·`test-mobile` 에서도 빠진다 — 조용히 빠지면 그 호스트에서 펌프가
        // 검사됐다고 오해한다. 이식성 가드(`check-ssh-pump-portable`)는 계속 돈다.
        const note = noteSkippedStep(b, "ssh-pump 단위 테스트", "POSIX 호스트 전용 — `check-ssh-pump-portable` 이 이식성은 계속 본다");
        test_step.dependOn(note);
        test_mobile_step.dependOn(note);
    }

    // **펌프는 리눅스로도 컴파일된다.** 이 파일은 세 경로(빌드 스크립트·NDK·Xcode)로 불리는데,
    // 표준 모드에 따라 glibc 가 POSIX 선언을 감춰 **한 경로에서만 깨지는** 일이 실제로 났다
    // (`-std=c11` 리눅스에서 `getaddrinfo` 가 사라져 CI 만 빨갰다). 여기서 그 조합을 상시 굽는다.
    const pump_linux = b.addObject(.{
        .name = "ssh-pump-linux",
        .root_module = b.createModule(.{
            .target = b.resolveTargetQuery(.{ .cpu_arch = .x86_64, .os_tag = .linux, .abi = .gnu }),
            .optimize = .Debug,
            .link_libc = true,
        }),
    });
    pump_linux.root_module.addIncludePath(b.path("src/platform/mobile"));
    pump_linux.root_module.addCSourceFile(.{
        .file = b.path("src/platform/mobile_host/ssh_pump.c"),
        .flags = &.{"-std=c11"},
    });
    const pump_linux_step = b.step("check-ssh-pump-portable", "Compile the SSH pump for linux-gnu (glibc feature macros)");
    pump_linux_step.dependOn(&pump_linux.step);
    boundary_step.dependOn(pump_linux_step);

    boundary_step.dependOn(&run_ime_commit_boundary_tests.step);

    // config 문서 → 실제 키 드리프트 가드. schema.zig의 doc-drift 가드가 "스키마 키가 표에 있는가"(정방향)를 막는 반면,
    // 이쪽은 "문서가 광고하는 키가 실재하는가"(역방향)를 막는다 — 문서만 보고 config에 적었는데 조용히 무시되던
    // 드리프트를 CI가 잡는다. docs/*.md를 런타임에 훑어야 해서(@embedFile은 디렉터리 순회 불가) 별도 테스트 바이너리로
    // 두고 cwd를 리포지토리 루트로 고정한다(boundary 테스트와 같은 구조). 단일 출처: docs/config-schema.md §7.
    const config_docs_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/config_docs/keys.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{.{ .name = "maru", .module = maru_mod }},
        }),
    });
    const run_config_docs_tests = b.addRunArtifact(config_docs_tests);
    run_config_docs_tests.setCwd(b.path("."));

    // 훅 인라인 커맨드는 **문자열 검사만으로 충분하지 않다**. stdin 을 삼키는지·가드에서 빠져나가는지·
    // 리다이렉션 실패까지 조용한지는 실제 셸을 돌려야 안다(그중 stderr 누출은 이 게이트가 실제로 잡았다).
    // 훅이 그 계약을 어기면 에이전트 턴이 멈추므로 상시 게이트로 둔다. POSIX 셸만 있으면 도는 검사다.
    const agent_hook_command_check = b.addSystemCommand(&.{ "sh", "tools/check-agent-hook-command.sh" });
    agent_hook_command_check.setCwd(b.path("."));
    // 진행 줄을 그대로 흘린다. 기본 정책은 stdout/stderr 를 캡처해 «출력이 있으면 실패»로 보는데,
    // 이 검사는 단계마다 `ok` 를 찍는 것이 진단의 절반이다 — 종료 코드만 본다.
    agent_hook_command_check.stdio = .inherit;
    const agent_hook_command_step = b.step("check-agent-hook-command", "Run the agent hook inline command against a real shell");
    agent_hook_command_step.dependOn(&agent_hook_command_check.step);
    test_step.dependOn(&agent_hook_command_check.step);

    const release_version_contract = b.addSystemCommand(&.{ "sh", "tools/test-release-version.sh" });
    release_version_contract.setCwd(b.path("."));
    release_version_contract.stdio = .inherit;
    const release_version_step = b.step("check-release-version", "Check release tag and macOS plist against the version SSOT");
    release_version_step.dependOn(&release_version_contract.step);
    test_step.dependOn(&release_version_contract.step);
    if (release_tag) |tag| {
        const release_tag_check = b.addSystemCommand(&.{
            "sh", "tools/render-macos-info-plist.sh", "check-tag", build_zig_zon.version, tag,
        });
        release_tag_check.setCwd(b.path("."));
        release_version_step.dependOn(&release_tag_check.step);
    }

    const github_release_publication_contract = b.addSystemCommand(&.{ "sh", "tools/test-github-release-publication.sh" });
    github_release_publication_contract.setCwd(b.path("."));
    github_release_publication_contract.stdio = .inherit;
    const github_release_publication_step = b.step("check-github-release-publication", "Check draft-first GitHub release publication");
    github_release_publication_step.dependOn(&github_release_publication_contract.step);
    test_step.dependOn(&github_release_publication_contract.step);

    const config_docs_step = b.step("check-config-docs", "Check config docs against the real schema keys");
    config_docs_step.dependOn(&run_config_docs_tests.step);

    // 문서 간 참조 가드. 링크 대상 파일뿐 아니라 **`#절-앵커`가 그 문서에 실재하는지**까지 본다 — 계약 문서를
    // 여러 파일로 가르면 파일은 그대로 있고 절만 옮겨가므로, 파일 존재만 보는 검사는 통과하는데 링크는 죽는다
    // (실측: 분할 한 번에 이 종류로만 8건). config-docs 게이트와 같은 구조로 cwd를 루트에 고정한다.
    const doc_link_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/doc_links/links.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    const run_doc_link_tests = b.addRunArtifact(doc_link_tests);
    run_doc_link_tests.setCwd(b.path("."));

    const doc_links_step = b.step("check-doc-links", "Check cross-document links and section anchors");
    doc_links_step.dependOn(&run_doc_link_tests.step);

    // session-host MRSH codec/framing 단위 테스트(P3). codec(protocol/framing/screen_stream/registry/server)은 std만
    // 쓰는 순수 계층이지만, macOS 전용 `runtime_manager`(P3-e2b)가 `@import("maru")`로 app InProcessTermBackend를
    // 재사용하므로 `maru` 모듈을 import로 준다(non-macOS 크로스컴파일에선 barrel이 runtime_manager를 제외해 maru가
    // 도달되지 않는다). 기본 `test` 스텝에 편입해 wire 회귀를 항상 잡고, `test-session-host`로 개별 실행도 가능하게 한다.
    const session_host_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/platform/macos/session_host.zig"),
            .target = target,
            .optimize = optimize,
            // socket_server(P3-d2a)가 unix socket syscall(socket/bind/accept/getpeereid)을 써서 libc를 링크한다.
            .link_libc = true,
            .imports = &.{.{ .name = "maru", .module = maru_mod }},
        }),
    });
    // `/usr/bin/env`가 build cache의 실제 `maru` artifact 경로를 test process에만 주입하고 test binary를 exec한다.
    // install step을 거치지 않으므로 `zig build test* --prefix ...`가 사용자 설치 경로를 쓰거나 덮어쓰지 않는다.
    const run_session_host_tests = b.addSystemCommand(&.{"/usr/bin/env"});
    run_session_host_tests.addPrefixedArtifactArg("MARU_SESSION_HOST_PRODUCT_EXE=", exe);
    const session_host_b3_0_4_step = b.step(
        "test-session-host-b3-0-4",
        "B3-0.4 attach execution transaction focused Debug and ReleaseFast gates",
    );
    const b3_debug_release_modes = .{
        std.builtin.OptimizeMode.Debug,
        std.builtin.OptimizeMode.ReleaseFast,
    };
    const session_host_b3_1_step = b.step(
        "test-session-host-b3-1",
        "B3-1 RPC response authority ownership focused Debug and ReleaseFast gates",
    );
    const session_host_b3_2_step = b.step(
        "test-session-host-b3-2",
        "B3-2 private destination admission focused Debug and ReleaseFast gates",
    );
    const session_host_b3_3_step = b.step(
        "test-session-host-b3-3",
        "B3-3 prepared request progress and write focused Debug and ReleaseFast gates",
    );
    const session_host_b3_4_5_step = b.step(
        "test-session-host-b3-4-5",
        "B3-4/5 RPC response publication ownership focused Debug and ReleaseFast gates",
    );
    const session_host_b3_6_step = b.step(
        "test-session-host-b3-6",
        "B3-6 internal RPC substrate strict completion Debug and ReleaseFast gates",
    );
    const session_host_2c3c_c1_step = b.step(
        "test-session-host-2c3c-c1",
        "2c3c C1 typed control facade Debug and ReleaseFast gates",
    );
    const session_host_2c3c_c2_step = b.step(
        "test-session-host-2c3c-c2",
        "2c3c C2 generation nonblocking control wiring Debug and ReleaseFast gates",
    );
    const session_host_2c3c_c3_step = b.step(
        "test-session-host-2c3c-c3",
        "2c3c C3 generation blocking control wiring Debug and ReleaseFast gates",
    );
    const session_host_2c3d_c1_step = b.step(
        "test-session-host-2c3d-c1",
        "2c3d C1 one-shot event facade Debug and ReleaseFast gates",
    );
    const session_host_2c3d_c2_step = b.step(
        "test-session-host-2c3d-c2",
        "2c3d C2 event release and quarantine Debug and ReleaseFast gates",
    );
    const session_host_2c3d_c3_1_step = b.step(
        "test-session-host-2c3d-c3-1",
        "2c3d C3-1 inline attachment event owner Debug and ReleaseFast gates",
    );
    const session_host_2c3d_c3_2_step = b.step(
        "test-session-host-2c3d-c3-2",
        "2c3d C3-2 purge-first product event drain Debug and ReleaseFast gates",
    );
