        });
        const run_recovery_contract_external_tests = b.addRunArtifact(
            recovery_contract_external_tests,
        );
        const recovery_contract_external_sentinel = b.addExecutable(.{
            .name = "maru-session-host-recovery-external-sentinel",
            .root_module = b.createModule(.{
                .root_source_file = b.path(
                    "tests/session_host_recovery_external_sentinel.zig",
                ),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{
                    .name = "client_external_pump",
                    .module = recovery_contract_external_tests.root_module,
                }},
            }),
        });
        const run_recovery_contract_external_sentinel = b.addRunArtifact(
            recovery_contract_external_sentinel,
        );
        const recovery_contract_pump_module = b.createModule(.{
            .root_source_file = b.path(
                "src/platform/macos/session_host/client_pump.zig",
            ),
            .target = target,
            .optimize = optimize,
        });
        const recovery_contract_sentinel = b.addExecutable(.{
            .name = "maru-session-host-recovery-contract-sentinel",
            .root_module = b.createModule(.{
                .root_source_file = b.path(
                    "tests/session_host_recovery_contract_sentinel.zig",
                ),
                .target = target,
                .optimize = optimize,
                .imports = &.{.{ .name = "client_pump", .module = recovery_contract_pump_module }},
            }),
        });
        const run_recovery_contract_sentinel = b.addRunArtifact(
            recovery_contract_sentinel,
        );
        const session_host_recovery_contract_step = b.step(
            "test-session-host-recovery-contract",
            "Run the non-empty recovery authority and ledger-token binding gate",
        );
        session_host_recovery_contract_step.dependOn(
            &run_recovery_contract_types_tests.step,
        );
        session_host_recovery_contract_step.dependOn(
            &run_recovery_contract_pump_tests.step,
        );
        session_host_recovery_contract_step.dependOn(
            &run_recovery_contract_external_tests.step,
        );
        session_host_recovery_contract_step.dependOn(
            &run_recovery_contract_external_sentinel.step,
        );
        session_host_recovery_contract_step.dependOn(
            &run_recovery_contract_sentinel.step,
        );

        // Buffered traversal fixtures stay outside the product barrel so test-only authority and
        // hostile allocators cannot become reachable from the shipped session-host module graph.
        const external_rx_turn_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path(
                    "src/platform/macos/session_host/client_external_rx_turn_test_support.zig",
                ),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        const run_external_rx_turn_tests = b.addRunArtifact(
            external_rx_turn_tests,
        );
        run_external_rx_turn_tests.setCwd(b.path("."));
        test_step.dependOn(&run_external_rx_turn_tests.step);
        session_host_step.dependOn(&run_external_rx_turn_tests.step);

        // C3 collector fixtures inject authority/read callbacks without making the transport-only
        // leaf or the product barrel depend on hostile test owners.
        const external_rx_read_tests = addProjectTest(b, .{
            .root_module = b.createModule(.{
                .root_source_file = b.path(
                    "src/platform/macos/session_host/client_external_rx_read_test_support.zig",
                ),
                .target = target,
                .optimize = optimize,
                .link_libc = true,
                .imports = &.{.{ .name = "maru", .module = maru_mod }},
            }),
        });
        const run_external_rx_read_tests = b.addRunArtifact(
            external_rx_read_tests,
        );
        run_external_rx_read_tests.setCwd(b.path("."));
        test_step.dependOn(&run_external_rx_read_tests.step);
        session_host_step.dependOn(&run_external_rx_read_tests.step);
    }

    // Opt-in external oracle: validates committed goldens against system libvterm.
    // Intentionally NOT wired into the default `test` step or `mise run check` so
    // the default build stays free of the libvterm dependency. Run it explicitly
    // with `zig build test-oracle-ext` (needs `brew install libvterm` or equivalent).
    const oracle_ext_mod = b.createModule(.{
        .root_source_file = b.path("tests/oracle/external.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .imports = &.{
            .{ .name = "maru", .module = maru_mod },
            .{ .name = "test_support", .module = test_support_mod },
        },
    });
    oracle_ext_mod.linkSystemLibrary("vterm", .{});
    oracle_ext_mod.addIncludePath(b.path("tests/oracle"));
    oracle_ext_mod.addCSourceFile(.{ .file = b.path("tests/oracle/vterm_shim.c") });
    const oracle_ext_tests = addProjectTest(b, .{ .root_module = oracle_ext_mod });
    const run_oracle_ext_tests = b.addRunArtifact(oracle_ext_tests);
    run_oracle_ext_tests.setCwd(b.path("."));

    const oracle_ext_step = b.step("test-oracle-ext", "Validate goldens against a real libvterm reference (requires libvterm)");
    oracle_ext_step.dependOn(&run_oracle_ext_tests.step);

    // Opt-in Ghostty oracle: validates goldens against libghostty-vt. Requires a
    // prebuilt static lib at references/ghostty/zig-out/lib/libghostty-vt.a (build
    // it with `mise exec zig@0.15.2 -- zig build -Demit-lib-vt=true` inside the
    // cloned Ghostty). NOT wired into the default `test` step or `mise run check`.
    const oracle_ghostty_mod = b.createModule(.{
        .root_source_file = b.path("tests/oracle/external_ghostty.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .imports = &.{
            .{ .name = "maru", .module = maru_mod },
            .{ .name = "test_support", .module = test_support_mod },
        },
    });
    oracle_ghostty_mod.addIncludePath(b.path("references/ghostty/include"));
    oracle_ghostty_mod.addIncludePath(b.path("tests/oracle"));
    oracle_ghostty_mod.addCSourceFile(.{ .file = b.path("tests/oracle/ghostty_shim.c") });
    oracle_ghostty_mod.addObjectFile(b.path("references/ghostty/zig-out/lib/libghostty-vt.a"));
    const oracle_ghostty_tests = addProjectTest(b, .{ .root_module = oracle_ghostty_mod });
    const run_oracle_ghostty_tests = b.addRunArtifact(oracle_ghostty_tests);
    run_oracle_ghostty_tests.setCwd(b.path("."));

    const oracle_ghostty_step = b.step("test-oracle-ghostty", "Validate goldens against Ghostty libghostty-vt (requires prebuilt libghostty-vt.a)");
    oracle_ghostty_step.dependOn(&run_oracle_ghostty_tests.step);

    // Opt-in Alacritty oracle: validates goldens against alacritty_terminal via a
    // prebuilt Rust dumper subprocess (tests/oracle/alacritty-dumper). Build it with
    // `cargo build --release` in that directory. NOT in the default `test`/`check`.
    const oracle_alacritty_mod = b.createModule(.{
        .root_source_file = b.path("tests/oracle/external_alacritty.zig"),
        .target = target,
        .optimize = optimize,
        .imports = &.{
            .{ .name = "test_support", .module = test_support_mod },
        },
    });
    const oracle_alacritty_tests = addProjectTest(b, .{ .root_module = oracle_alacritty_mod });
    const run_oracle_alacritty_tests = b.addRunArtifact(oracle_alacritty_tests);
    run_oracle_alacritty_tests.setCwd(b.path("."));

    const oracle_alacritty_step = b.step("test-oracle-alacritty", "Validate goldens against Alacritty alacritty_terminal (requires prebuilt Rust dumper)");
    oracle_alacritty_step.dependOn(&run_oracle_alacritty_tests.step);

    const stress_options = b.addOptions();
    stress_options.addOption(bool, "soak", false);
    const stress_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/stress/core.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "test_support", .module = test_support_mod },
                .{ .name = "stress_options", .module = stress_options.createModule() },
            },
        }),
    });
    const run_stress_tests = b.addRunArtifact(stress_tests);
    run_stress_tests.setCwd(b.path("."));

    const stress_step = b.step("test-stress", "Run quick deterministic stress tests");
    stress_step.dependOn(&run_stress_tests.step);

    const stress_soak_options = b.addOptions();
    stress_soak_options.addOption(bool, "soak", true);
    const stress_soak_tests = addProjectTest(b, .{
        .root_module = b.createModule(.{
            .root_source_file = b.path("tests/stress/core.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
                .{ .name = "test_support", .module = test_support_mod },
                .{ .name = "stress_options", .module = stress_soak_options.createModule() },
            },
        }),
    });
    const run_stress_soak_tests = b.addRunArtifact(stress_soak_tests);
    run_stress_soak_tests.setCwd(b.path("."));

    const stress_soak_step = b.step("test-stress-soak", "Run longer opt-in stress tests");
    stress_soak_step.dependOn(&run_stress_soak_tests.step);

    const perf_exe = b.addExecutable(.{
        .name = "maru-perf",
        .root_module = b.createModule(.{
            .root_source_file = b.path("tools/perf/core.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
            },
        }),
    });
    const run_perf = b.addRunArtifact(perf_exe);
    run_perf.setCwd(b.path("."));

    const perf_step = b.step("perf", "Run local performance budget harness");
    perf_step.dependOn(&run_perf.step);

    // 셰이핑 run 분포 조사 도구(예산 게이트가 아니라 measure-first용). 지금 native 셰이퍼는 셀마다
    // CTLine을 만드는데, 연속 run 하나로 묶으면 호출이 몇 배 줄어드는지를 실제 출력으로 재서 묶기
    // 작업의 기대 이득을 추정이 아닌 실측으로 확정한다.
    const shape_run_probe_exe = b.addExecutable(.{
        .name = "maru-shape-run-probe",
        .root_module = b.createModule(.{
            .root_source_file = b.path("tools/perf/shape_run_probe.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "maru", .module = maru_mod },
            },
        }),
    });
    const run_shape_run_probe = b.addRunArtifact(shape_run_probe_exe);
    run_shape_run_probe.setCwd(b.path("."));
    if (b.args) |args| run_shape_run_probe.addArgs(args);

    const shape_run_probe_step = b.step("shape-run-probe", "Measure shaping run distribution (measure-first)");
    shape_run_probe_step.dependOn(&run_shape_run_probe.step);
}

fn swiftMacOSTarget(b: *std.Build, target: std.Target) []const u8 {
    const arch = switch (target.cpu.arch) {
        .aarch64 => "arm64",
        .x86_64 => "x86_64",
        else => @panic("macOS Swift app host only supports arm64 and x86_64 targets"),
    };
    const version = target.os.version_range.semver.min;
    return b.fmt("{s}-apple-macosx{d}.{d}", .{ arch, version.major, version.minor });
}

/// **호스트에서 빠지는 스텝이 조용히 초록이 되지 않게** 한 줄을 남긴다.
///
/// 아무것도 안 만드는 스텝은 `zig build <이름>` 이 아무 말 없이 exit 0 이라, 그 기기의 개발자가
/// "돌았다" 고 읽는다 — 이 저장소가 이미 밟은 함정이다(체크가 0 개인데 전부 초록으로 본 사고).
/// 실패시키지는 않는다: 그 호스트에 소비자가 없어서 빠지는 것이지 무언가 깨진 것이 아니다.
fn noteSkippedStep(b: *std.Build, step_name: []const u8, reason: []const u8) *std.Build.Step {
    const Note = struct {
        fn make(step: *std.Build.Step, _: std.Build.Step.MakeOptions) anyerror!void {
            std.debug.print("{s}\n", .{step.name});
        }
    };
    const s = b.allocator.create(std.Build.Step) catch @panic("OOM");
    s.* = std.Build.Step.init(.{
        .id = .custom,
        .name = b.fmt("[skip] {s}: {s}", .{ step_name, reason }),
        .owner = b,
        .makeFn = Note.make,
    });
    return s;
}
